window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_017"]={"n":"吴当","dyn":"元","poems":[{"t":"明良诗 其一","f":"曲","c":["于赫皇祖，肇基朔土。","惟时忠襄，实佐神武。"]},{"t":"明良诗 其二","f":"曲","c":["天戈攸指，罔不率俾。","忠武之才，雄特瑰伟。"]},{"t":"明良诗 其三","f":"曲","c":["逮乎忠宣，相我世皇。","式开治平，统一万方。"]},{"t":"明良诗 其四","f":"曲","c":["猗与文忠，礼乐是式。","克赞英庙，以匡以翼。"]},{"t":"明良诗 其五","f":"曲","c":["硕硕元勋，后先四王。","维君之明，维臣之良。"]},{"t":"明良诗 其六","f":"曲","c":["侃侃开府，尚德象贤。","承厥父祖，佛时仔肩。"]},{"t":"明良诗 其七","f":"曲","c":["惟皇之念，翰墨是锡。","倅尔嘉名，休光有奕。"]},{"t":"明良诗 其八","f":"曲","c":["云汉于昭，发耀天藻。","垂美无疆，永以为宝。"]},{"t":"明良诗 其九","f":"曲","c":["翼翼厥明，终始典学。","陈善责难，世臣攸托。"]},{"t":"明良诗 其十","f":"曲","c":["以道事君，汝翼汝为。","股肱左右，庶底缉熙。"]},{"t":"明良诗 其十一","f":"曲","c":["明良之逢，有典有则。","世笃忠贞，式报天德。"]},{"t":"恒德斋为开府明良公作 其一","f":"曲","c":["于穆天命，恒久不已。","往禅来续，与道为体。"]},{"t":"恒德斋为开府明良公作 其二","f":"曲","c":["惟圣有德，率性之常。","不二不杂，悠久无疆。"]},{"t":"恒德斋为开府明良公作 其三","f":"曲","c":["君子是则，勉勉不息。","终始弗渝，夙夜无斁。"]},{"t":"恒德斋为开府明良公作 其四","f":"曲","c":["赫赫元勋，昔佐皇祖。","配德惟一，永锡胤祚。"]},{"t":"恒德斋为开府明良公作 其五","f":"曲","c":["侃侃闻孙，靖共在位。","式谨尔常，以赞天子。"]},{"t":"恒德斋为开府明良公作 其六","f":"曲","c":["佩舄雍雍，退食自公。","肃慎斋居，用省厥躬。"]},{"t":"恒德斋为开府明良公作 其七","f":"曲","c":["协于克一，责难将美。","徵其化成，万国咸理。"]},{"t":"恒德斋为开府明良公作 其八","f":"曲","c":["惟巽而动，勿承以羞。","亿万斯年，于昭匹休。"]},{"t":"极高明亭诗为曾以敬作 其一","f":"曲","c":["春木载荣，朝阳孔曦。","悠悠白云，华盖之西。"]},{"t":"极高明亭诗为曾以敬作 其二","f":"曲","c":["爰有新亭，翼翼中峙。","式究尔宁，君子攸止。"]},{"t":"极高明亭诗为曾以敬作 其三","f":"曲","c":["其止维何，朝弦莫歌。","道其问学，弗辟弗颇。"]},{"t":"极高明亭诗为曾以敬作 其四","f":"曲","c":["斯道之著，皎焉日星。","发育峻极，敛之灵扃。"]},{"t":"极高明亭诗为曾以敬作 其五","f":"曲","c":["弥纶六合，迥绝寥廓。","周知旁行，卓彼先觉。"]},{"t":"极高明亭诗为曾以敬作 其六","f":"曲","c":["如俯层台，洞视靡遗。","如持悬鉴，罔有蔽亏。"]},{"t":"极高明亭诗为曾以敬作 其七","f":"曲","c":["知崇效天，礼卑法地。","成性之存，内外交致。"]},{"t":"极高明亭诗为曾以敬作 其八","f":"曲","c":["万物毕备，一贯斯全。","参乎有唯，思也是传。"]},{"t":"极高明亭诗为曾以敬作 其九","f":"曲","c":["予忝承学，子实名裔。","自顾无闻，祇用生愧。"]},{"t":"极高明亭诗为曾以敬作 其十","f":"曲","c":["惟博反约，实基三省。","敢曰尚友，愿以自警。"]},{"t":"庆原堂诗为萍乡刘氏作 其一","f":"曲","c":["惟楚萍乡，邑里有堂。","繄昔刘氏，肇基于唐。"]},{"t":"庆原堂诗为萍乡刘氏作 其二","f":"曲","c":["雄虎之台，郁郁丘土。","其伏未耀，本干深固。"]},{"t":"庆原堂诗为萍乡刘氏作 其三","f":"曲","c":["子孙多贤，冠佩蝉联。","积善储和，溯流而源。"]},{"t":"庆原堂诗为萍乡刘氏作 其四","f":"曲","c":["福庆之实，既坚既栗。","晔晔灵芝，毓秀于室。"]},{"t":"庆原堂诗为萍乡刘氏作 其五","f":"曲","c":["历宋而元，流庆未已。","袒免同居，表德闾里。"]},{"t":"庆原堂诗为萍乡刘氏作 其六","f":"曲","c":["山冢之迁，有霆有雷。","尚复多祉，源源其来。"]},{"t":"庆原堂诗为萍乡刘氏作 其七","f":"曲","c":["奕奕君子，实居后麓。","既休既宁，以踵芳躅。"]},{"t":"庆原堂诗为萍乡刘氏作 其八","f":"曲","c":["绳绳厥承，忠厚之教。","庶其绍之，以食斯报。"]},{"t":"庆原堂诗为萍乡刘氏作 其九","f":"曲","c":["太史有记，邦人足徵。","式勖来嗣，勒诗尔楹。"]},{"t":"咸阳王功德诗 其一","f":"曲","c":["在昔皇祖，有赫神武。","维忠宣王，杰出西土。"]},{"t":"咸阳王功德诗 其二","f":"曲","c":["佐命而兴，来受圭组。","宪宗伐蜀，往补戎伍。"]},{"t":"咸阳王功德诗 其三","f":"曲","c":["于穆世皇，天戈载扬。","亲拔云南，用逖蛮方。"]},{"t":"咸阳王功德诗 其四","f":"曲","c":["滇之宗臣，乃悖纪纲。","复叛不顺，袭盗以狂。"]},{"t":"咸阳王功德诗 其五","f":"曲","c":["天子曰嘻，孰称予使。","爰命忠惠，以绥以抚。"]},{"t":"咸阳王功德诗 其六","f":"曲","c":["谕之恩信，涤汝烦苦。","简节疏目，咸得理所。"]},{"t":"咸阳王功德诗 其七","f":"曲","c":["乃疆乃理，奠尔城邑。","市有居货，屋有陶甓。"]},{"t":"咸阳王功德诗 其八","f":"曲","c":["我田我池，粳稌黍稷。","训厥士女，污俗斯革。"]},{"t":"咸阳王功德诗 其九","f":"曲","c":["既庶既富，建学立教。","笾豆鼓钟，于乐孔庙。"]},{"t":"咸阳王功德诗 其十","f":"曲","c":["诗书歌弦，孰则孰效。","折其狂猘，笃尔忠孝。"]},{"t":"咸阳王功德诗 其十一","f":"曲","c":["步不出国，侯幽侯深。","部曲联绎，干戈若林。"]},{"t":"咸阳王功德诗 其十二","f":"曲","c":["久而弥孚，向义骎骎。","锡贡无已，大赂南金。"]},{"t":"咸阳王功德诗 其十三","f":"曲","c":["天祚皇国，克生伟人。","历年孔多，以福远民。"]},{"t":"咸阳王功德诗 其十四","f":"曲","c":["远民之安，克顺克正。","惟王之贤，天子之圣。"]},{"t":"咸阳王功德诗 其十五","f":"曲","c":["元臣云亡，远民孔哀。","风马云车，曷往曷来。"]},{"t":"咸阳王功德诗 其十六","f":"曲","c":["新庙既作，执事有恪。","王其享兹，用配诸葛。"]},{"t":"咸阳王功德诗 其十七","f":"曲","c":["锡爵启封，皇则悼之。","嗣德象贤，天实报之。"]},{"t":"咸阳王功德诗 其十八","f":"曲","c":["诜诜孙子，有引无替。","太史作诗，式昭永世。"]},{"t":"性乐堂诗 其一","f":"曲","c":["繄厥成性，浩然其天。","灵明洞彻，溥博渊泉。","万物毕备，众善具全。","反身而诚，乐莫大焉。"]},{"t":"性乐堂诗 其二","f":"曲","c":["惟尔学者，夙夜有恪。","循端致曲，实充实扩。","昭兹本善，以踵先觉。","观其回通，亦底克乐。"]},{"t":"性乐堂诗 其三","f":"曲","c":["翼翼高堂，攸介攸宁。","天光丕容，匪间显冥。","灼之当为，勇往是程。","其则不远，勒诗在楹。"]},{"t":"集义斋诗为太行高氏作 其一","f":"曲","c":["瞻彼嘉木，太行之阴。","盘盘幽谷，侃侃素心。"]},{"t":"集义斋诗为太行高氏作 其二","f":"曲","c":["缅焉兴怀，古道是式。","惟心之宜，至当有则。"]},{"t":"集义斋诗为太行高氏作 其三","f":"曲","c":["我其扩之，制事不违。","用达万变，审乎先几。"]},{"t":"集义斋诗为太行高氏作 其四","f":"曲","c":["灼知勇为，乃积乃充。","无间微显，集于厥躬。"]},{"t":"集义斋诗为太行高氏作 其五","f":"曲","c":["浩然之生，实匪助长。","天地之塞，吾体同量。"]},{"t":"集义斋诗为太行高氏作 其六","f":"曲","c":["肃尔斋居，永端于初。","必有事焉，昭昭圣谟。"]},{"t":"致亭诗 其一","f":"曲","c":["瞻彼绎山，绵绵其麓。","爰有君子，乐尔贞卜。","有倬斯亭，荫此嘉木。","悠悠永歌，衍衍春服。"]},{"t":"致亭诗 其二","f":"曲","c":["先民有觉，昧兹寡闻。","我其致之，匪学曷敦。","问辨言析，反思其存。","焕若融彻，大明初暾。"]},{"t":"致亭诗 其三","f":"曲","c":["顾瞻周行，玄邈奚绪。","曷其致之，惟圣有矩。","我车既坚，我马孔阜。","无远弗至，式谷尔御。"]},{"t":"致亭诗 其四","f":"曲","c":["潏彼川流，昼夜斯逝。","溯溯无端，原原无已。","于惟缉熙，不杂不二。","我是用希，夙夜敬止。"]},{"t":"致亭诗 其五","f":"曲","c":["既种既耨，廪积孔殷。","既狩既猎，鼎餗具陈。","秩秩大猷，俛焉日新。","勖尔尚友，予亦何人。"]},{"t":"脩省斋诗 其一","f":"曲","c":["惟皇降衷，弗忚弗亏。","习远情肆，始沦以隳。"]},{"t":"脩省斋诗 其二","f":"曲","c":["有卓君子，励行自修。","夙夜惕若，反躬是求。"]},{"t":"脩省斋诗 其三","f":"曲","c":["孰去孰存，惟日内省。","百鏬勿遗，靡伺靡骋。"]},{"t":"脩省斋诗 其四","f":"曲","c":["脩省之始，尤慎在独。","勇绝其萌，庶制尔欲。"]},{"t":"脩省斋诗 其五","f":"曲","c":["于赫斯临，昭昭幽深。","毋苟自欺，其敢弗钦。"]},{"t":"脩省斋诗 其六","f":"曲","c":["矧兹明威，曷敢戏豫。","战兢自持，主一无二。"]},{"t":"脩省斋诗 其七","f":"曲","c":["燕居观象，恒若荐雷。","益慎益戒，万善具来。"]},{"t":"脩省斋诗 其八","f":"曲","c":["审之靡疚，式底于完。","信立愿达，克承克安。"]},{"t":"脩省斋诗 其九","f":"曲","c":["吾侪小人，贪欲内锢。","甘心物欲，有寐有寤。"]},{"t":"脩省斋诗 其十","f":"曲","c":["为之由己，曷自暴弃。","呜呼灵台，幸勖尔志。"]},{"t":"寿宁堂诗为冀宁耿氏作 其一","f":"曲","c":["于昭秉彝，有本有支。","立爱惟亲，万善是基。"]},{"t":"寿宁堂诗为冀宁耿氏作 其二","f":"曲","c":["衎衎令子，报德慈母。","菀兹堂构，有翼其宇。"]},{"t":"寿宁堂诗为冀宁耿氏作 其三","f":"曲","c":["鱼轩戾止，兄弟具在。","执礼循循，百福攸介。"]},{"t":"寿宁堂诗为冀宁耿氏作 其四","f":"曲","c":["旨甘孔时，春酒载筵。","天锡纯嘏，眉寿永年。"]},{"t":"寿宁堂诗为冀宁耿氏作 其五","f":"曲","c":["哺乌在林，遗我好音。","起处攸宁，式慰母心。"]},{"t":"寿宁堂诗为冀宁耿氏作 其六","f":"曲","c":["琴瑟静好，以雅以南。","式歌且舞，朱衣华簪。"]},{"t":"寿宁堂诗为冀宁耿氏作 其七","f":"曲","c":["既曰寿只，实在宁只。","夙夜凊温，庶其敬止。"]},{"t":"寿宁堂诗为冀宁耿氏作 其八","f":"曲","c":["敦孝移忠，永锡不匮。","矢诗孔扬，以勖来裔。"]},{"t":"四月朔都门别友","f":"五言律诗","c":["昨日送春归，今朝送君去。","君去几时来，春归向何处。","都门柳千行，晴空正飞絮。","祇恐尊酒空，离情渺无据。"]},{"t":"拂云堂","f":"五言律诗","c":["脩竹临绿水，高堂散清阴。","猗猗岁寒操，皎皎君子心。","不承春阳媚，已觉秋露深。","仰止云汉上，高节慎所任。"]},{"t":"凤冈隐居 其一","f":"五言律诗","c":["凤凰千仞冈，中有隐者庐。","流水绕屋下，青山当座隅。","邻曲不在多，聊可共耕锄。","种菊秋露重，斸花春雨馀。"]},{"t":"凤冈隐居 其二","f":"五言律诗","c":["松下挥鸣弦，凉风满庭除。","振衣红尘表，濯缨清水渠。","虚名果何益，此乐将焉如。","伊人幸同姓，行矣巾吾车。"]},{"t":"送刘山人远游","f":"五言古诗","c":["初夏风日清，芳华尽披委。","萧萧野人居，绿树净如洗。","繁阴在庭户，晴云隔窗纸。","刘君负绝艺，幽讨亦戾止。","平生一緉屐，历历几千里。","南袖岭峤烟，东拂扶桑水。","空斋坐终日，论议颇亹亹。","言立罔迷真，浩瀚况无已。","群流会一原，众辙不殊轨。","昆仑倚西极，黄河走其底。","嵩华与恒岱，郁郁土中峙。","休气蓄灵光，自惜伯玉址。","结交燕赵豪，跃马长杨里。","堂堂百年身，兹游更奇伟。","酌酒浇壮怀，奋步从此始。"]},{"t":"送曾冲衍自甥馆归省","f":"五言古诗","c":["慨我林壑姿，高思凌云烟。","清秋到城邑，兼旬得留连。","耆旧颇凋谢，新知多少年。","曾君金川彦，胤胄本蝉联。","华姻照高阅，玉树来鸾鹓。","自小涉书史，已能缀诗篇。","相值阛阓间，被服华且鲜。","间亦能我即，辞气自温妍。","而翁富文学，传家有渊源。","十年不相见，使我心悁悁。","奇骨出名驹，风采固超然。","尔邑危处士，其人萟且贤。","词高连城价，字重青瑶镌。","汝能早入室，累岁相周旋。","吾闻古人学，忠信盖所先。","彝伦本日用，昭著无幽玄。","本干既有立，华实自芬蕃。","愿言勤孝弟，馀力及艺文。","友道贵责善，我歌匪虚言。"]},{"t":"同诸彦泛舟游","f":"五言古诗","c":["移舟荡绿水，棹击来清风。","山树接天碧，汀花向日红。","圭璋益良朋，群簪得相从。","窈窕杨柳外，逶迤墟里东。","微雨洒芳郊，流水度晴虹。","渔歌日暮起，清响紫烟中。"]},{"t":"九日江楼分韵赋采字","f":"五言古诗","c":["江上秋风多，客里时序改。","嘉菊空满目，幽香为谁采。","江楼对西山，物景颇潇洒。","山云寒冉冉，汀树晴蔼蔼。","何以慰今朝，浊醪向邻买。","野馔在盘餐，梨栗杂醯醢。","眷兹二三友，被服盛兰茝。","举盏送飞鸿，翩翩望沧海。"]},{"t":"赋灵碧石山子","f":"五言律诗","c":["卷石重拱璧，致之果何从。","隐几当翠微，娟娟秀芙蓉。","艮岳玄雾温，香炉紫烟重。","五老不可见，令我忆鳌峰。"]},{"t":"送吾安之令渤海县","f":"五言古诗","c":["奉诏出高阙，驱车向长河。","长河正奔崩，大野仍横戈。","宵衣动深忧，频岁秋无禾。","今君宰渤海，敷政当如何。","上以畅皇惠，下以拯民疴。","清宫执道要，直气排洄波。","东郊散壶榼，月户鸣机梭。","境内鸡犬静，垄头牛马多。","游人若云环，窭室皆春和。","遄归赞天纬，报最无蹉跎。"]},{"t":"汪氏桃溪先业","f":"五言古诗","c":["种桃作春华，插柳被涧阿。","飞梁度窈窕，峭壁缠烟萝。","游息各有地，简编足吟哦。","宜有遁世者，看云时一过。","先庐倚丘坟，岁晏伤如何。"]},{"t":"送丑时中安陆知府","f":"五言古诗","c":["烝庶日凋敝，久贻宵旰忧。","中原有斗格，陋室仍诛求。","又闻大河奔，无复桑田收。","群情自嗷嗷，时论空悠悠。","下诏选朝士，传声典方州。","及兹数年来，令牧颇清修。","皇帝威信布，膏泽亦下流。","用副民社寄，庶答廊庙谋。","君才已历试，儒术素所优。","寒露承冰壶，黄钟播天球。","楚郢古名邦，廛市接车舟。","人多尚游贩，野有良田畴。","坐令书牒稀，行见疮痍瘳。","香凝棨戟静，雨洽桑麻稠。","问俗在抚摩，敷政尚怀柔。","三年屡丰穰，五裤成歌讴。","最书举劳绩，归来奏宸旒。"]},{"t":"送李伯微山东廉使赋华不注峰","f":"五言古诗","c":["华峰秀亭亭，缥缈风雨会。","湖光纳空翠，元气蓄冥昧。","云来泰山颠，日出方丈外。","孤根奠地轴，万木动天籁。","危攀望不极，高致君应最。","使节无滞留，都人仰旌旆。"]},{"t":"送赵大本西台御史得一字","f":"五言古诗","c":["关陕古雄都，四塞若天室。","圣人物土贡，沃壤称第一。","皇威极西邮，声教无远昵。","崇台揽纪纲，郡国底宁谧。","赵君金闺彦，楚楚冰玉质。","出身翰墨场，已执太史笔。","朝峨惠文冠，夕策长亭驲。","弭节都门道，供帐集簪韠。","朔风吹秦陇，岳色寒崒嵂。","泾渭扬浊清，河水相荡潏。","皇皇霜简动，肃肃绣衣出。","丈夫报国心，重在理仁术。","矧兹圣明时，布衣靡阙失。","胡为守牧宰，往往败绳律。","饥渴剧饫饕，民隐讵遑恤。","岂无循良才，众丑成妒嫉。","遂令白黑挠，惩劝恒过实。","周询待摩抚，伺察到微密。","于焉振风采，勿使废彀率。","遄归报明廷，烟柳动春日。"]},{"t":"西屿书堂","f":"五言古诗","c":["高堂在西屿，积水宜清秋。","飞梁接广衍，松竹何翛翛。","草色洲渚净，书声庭户幽。","美人水苍佩，公子木兰舟。","及兹且容与，乐哉以忘忧。"]},{"t":"横州新城","f":"五言古诗","c":["守国设险阨，由来固金汤。","天下已一家，四海无封疆。","边夷失摩抚，虚邑奔豺狼。","横州两江上，妖氛日相望。","烈烈四野焚，哀哀万民疮。","倪君列半刺，为政古循良。","及兹幸辑睦，庶以安苍黄。","兵威尚形势，邦本资堤防。","版筑不辞劳，恩波浩难量。","神功实天相，良甓发地藏。","遂令千年间，集此百雉强。","坐见云鸟陴，居然山水乡。","嵯峨超楼橹，迢递蟠池隍。","落日笳鼓壮，寒风旌旆扬。","廛区表井里，公馆临康庄。","蔼蔼闻士誉，熙熙浃时康。","从兹慎备禦，奚用多斗伤。","长松在涧底，至宝委道傍。","鸾栖自枳棘，鹓路空翱翔。","谁持太史书，为贡白玉堂。"]},{"t":"谢灵运小像","f":"五言古诗","c":["达人不偶俗，穷乃托遐踪。","海上采石华，山头接云松。","旷情凌霄外，长笑紫烟重。","白驹不可絷，矫若人中龙。","世诐道已微，君子固有穷。","多才竟为累，寡立复谁从。","凄凉贝锦诗，千载仍忡忡。"]},{"t":"兰石竹树图","f":"五言律诗","c":["光风被丛兰，秀气何绸缪。","竹树露已深，萧萧苔石幽。","亦有纫佩者，襭芳在中洲。","含情欲谁寄，湘水何悠悠。"]},{"t":"渊明图","f":"五言古诗","c":["窈窕墟里烟，崎岖抚遐踪。","松菊在三径，归来事春农。","乘化乐天命，千古垂高风。"]},{"t":"菊泉轩","f":"五言律诗","c":["种菊秋水上，泉甘花更妍。","掇英挹朝露，牵萝媚清涟。","衡门幽且閒，沦迹托贞坚。","浊酒有深趣，乐哉以忘年。"]},{"t":"送立道","f":"五言律诗","c":["清笳动城阙，落叶响空井。","羁客增远怀，繁霜集寒景。","依依塞鸿度，杳杳江路永。","昨夜梦沧洲，朝来理烟艇。"]},{"t":"送无悦上人归高句骊","f":"五言古诗","c":["折芦渡海水，诸方记遐踪。","东穷会稽岭，南登祝融峰。","赤城霞绮多，香炉紫烟重。","平生几緉屐，伴此九节筇。","昨者来阙下，祗园忆相逢。","燕坐永夜灯，翻经清曙钟。","一彻了空寂，真际何从容。","法云散天华，珠光起神龙。","上人既东归，正法信有宗。","亦欲乘桴行，同心幸相从。"]},{"t":"云林图","f":"五言古诗","c":["吾邦宅冲奥，盘礴元气会。","嵯峨临川山，遐眺八极外。","日月有耿光，万象破冥昧。","云林隔沧洲，秀色翼华盖。","岩桂芳未歇，青霞宜有待。","愿息轩冕游，眷兹岁年改。"]},{"t":"寄题周炼师云台真馆","f":"五言古诗","c":["亭亭云台山，重阜隐深廓。","神宫辟龙虎，秀色今绵邈。","真馆依青林，涧水傍虚阁。","种竹春雾重，刊松晴雪落。","高敞自无为，幽旷各有托。","时见白云閒，为雨出城郭。","岂知有道者，元化在机握。","相从赤松游，不为慕灵药。","愧我烦世虑，眷然仰冥漠。","考槃能自引，随遇有真乐。","园绮如可期，共尔戒归鹤。"]},{"t":"赋谦斋","f":"五言律诗","c":["为山郁穹窿，乃处厚地中。","君子有令德，逊志息微躬。","种菊春雨洽，纫兰秋露浓。","斋居玩易象，素履慎初终。"]},{"t":"赋渊明归来图送致仕者","f":"五言古诗","c":["苍苍庐山阳，渺渺彭蠡东。","依依柴桑里，矫矫靖节翁。","聊为三径资，出宰古县中。","折腰未为辱，自眷菊与松。","幡然赋归来，高眠北窗风。","素琴既无弦，尊酒亦屡空。","篮舆入净社，植杖随春农。","逍遥有真乐，畴能继其踪。","君生千载后，出处慎初终。","解印返故山，栖此环堵宫。","作图励薄俗，相与传无穷。"]},{"t":"送胡宗悦官长沙","f":"五言律诗","c":["五夜霜露集，秋风起城头。","出门送行客，对酒总离忧。","红树接郊甸，白蘋满汀洲。","南望长沙云，湘水寒悠悠。"]},{"t":"委羽山潘氏隐居","f":"五言古诗","c":["天台几千仞，秀色浮苍穹。","下有委羽山，迢迢赤城东。","晴湍激飞瀑，灵鹊巢长松。","眷彼遗世士，诛茅白云通。","筑室倚飞霞，开轩待清风。","种菊充糇粮，插槿当垣墉。","孤高性所玩，夷旷思无穷。","击壤节酣歌，据石抚丝桐。","迕俗幸无累，寡欲不期丰。","谁刊蒋诩径，庶蹑羊求踪。","予将息尘鞍，赏心冀能同。"]},{"t":"高氏新构大行书院","f":"五言古诗","c":["嵯峨大行东，陵麓正延广。","池河发芳滋，耕凿乐膏壤。","之子慎素履，义路思独往。","黉宫宅幽贞，神宇肃弘敞。","空翠在庭户，嘉木日以长。","荐豆不违矩，奠席歘来享。","童冠列春服，歌弦发清响。","古学贵得师，景行属高仰。","车马远可致，山水良足赏。","焉得挂朝衣，为尔息尘鞅。"]},{"t":"琴鹤双清亭","f":"五言古诗","c":["结亭绝嚣尘，窈窕北堂东。","新竹雨满林，老树云半空。","开轩纳归鹤，据石理丝桐。","昔贤尚高洁，以此随行踪。","尔祖罄遐思，坚贞副深衷。","锡谥既有尚，素心谅能同。","水木托本源，芳润信无穷。","大雅继宏响，遗书满庭中。","工歌赞前勋，述德宁有终。","何时戒仙驭，抚席聆仙风。"]},{"t":"送桂道士","f":"五言古诗","c":["桂子怀武夷，翩翩向东粤。","褰云采石华，著屐踏海月。","我昔留豫章，尔祖尤清狂。","高居太古楼，呼酒时飞觞。","一别上京国，屡献匡时策。","桃李漫成蹊，秋风改颜色。","持节拥貔貅，干戈遍南州。","誓将扫氛祲，少纾黄屋忧。","流云翳太清，谪宦向江城。","忆听西山雨，对酒写离情。","羡子神仙器，去击沧浪枻。","不辞行路难，独鹤思凌厉。","青山九曲溪，每曲可幽栖。","日暮棹歌里，剑光起虹霓。","仰挹浮丘袂，頫流贾生涕。","真隐倘相逢，为述烟霞志。"]},{"t":"丛桂轩九日书怀","f":"五言古诗","c":["桂树得秋雨，清芬散馀葩。","嘉节百感集，寒菊不见花。","尘爵幸未虚，乡山久无家。","悠悠任天运，兀兀展物华。","仲尼不复梦，夷齐何怨嗟。","岂无西山薇，亦有东陵瓜。","贞心谅谁同，良友各天涯。","张鶱使绝域，能驾寻河槎。","陶潜愿躬耕，早命归田车。","我独伤局促，爱兹绝纷哗。","方期煮白石，对君引流霞。"]},{"t":"灯夕","f":"五言律诗","c":["千山动残寒，万里有积雪。","云影互往还，江光乍明灭。","居人灯火寂，城堞笳鼓歇。","忧端感时序，取酒消愤结。"]},{"t":"送李黼脩撰以旱请祷代祀嵩衡淮海","f":"五言古诗","c":["帝命脩群祀，天香播八埏。","春秋王正月，历数史逾年。","云汉忧时切，皇华遣使贤。","鳌头金榜客，鹤背玉堂仙。","授节来三殿，传宣下九天。","百年周礼乐，万国禹山川。","冠冕移班序，车书际幅员。","淮流桐柏导，岳影外方连。","望秩严稽典，相诚远致虔。","过家娱采服，聚德焕奎躔。","紫气浮燕蓟，青郊接涧瀍。","杂花旌茷茷，芳草马翩翩。","鱼佩横雕玉，鲛绡细织涎。","暮云低楚树，春水涨吴船。","瀚海飞龙外，衡阳落雁边。","祠官罗鼎俎，庭石丽牲牷。","降祼先明齐，登歌间宿县。","合萧馨黍稷，沈璧达渊泉。","圭币黄金藉，文章琬琰镌。","幽灵瞻肸向，纯嘏锡绵延。","麻麦千郊雨，弦歌万里烟。","底今民物阜，无复岁时愆。","问俗裨皇政，封章进御筵。","大夫勤奉职，汗竹纪长篇。"]},{"t":"天历初元京师之变大兴军旅中外皇皇遄闻顺附诛放奸臣朝廷清明海宇宁一皇帝神圣郊天告庙躬行典礼酬功报力恩泽周溥大宥涤濯仁施滂沛百官称庆宾筵秩秩进贤去邪皆繇睿断太平之运适符於今草野愚臣谨摭所闻著为歌咏以称述盛德愧辞语芜谫不足备太史之采传示久远云尔共八十韵","f":"五言古诗","c":["社稷初闻变，朝廷欲托孤。","群情迎代邸，至德辟勾吴。","大业中兴主，方舆混一图。","威声通海岱，神采动江湖。","邮传三千里，舟车百万夫。","共知尊帝统，犹或窃兵符。","政体萧曹辅，权纲耿贾扶。","天机开武略，相国发雄谟。","未足烦游刃，惟宜破大軱。","先锋初出锐，全阵已摧枯。","义正师无敌，城降戒不屠。","乾坤司化育，民物尽昭苏。","颂祷千官集，朝宗万国孚。","勋庸荣阀阅，社土赐茅蒩。","隐恻纶音切，优嘉宠数殊。","酬功颁府藏，怜死恤妻孥。","始觉埃坌静，遄闻沛泽敷。","近圻仍给复，内郡悉蠲租。","宥自深仁施，情矜旧染洿。","廛征随刬涤，缧绁遽欢呼。","玉烛调苍律，阳和转碧芜。","祥开山出瓮，瑞应火流乌。","会合宁非数，休祯信不诬。","淳风还揖让，彝训协都俞。","公器岩廊备，卿材柱石须。","合袪登衮衮，览德下于于。","裹甲宁论武，紬书半用儒。","步联青琐闼，坐列锦氍毹。","金马天门邃，铜驼御路迂。","考耆视禘礿，报事享郊雩。","牢醴周彝鼎，粢盛夏琏瑚。","祀皆稽典礼，诚岂荐潢污。","宗社金为室，庭碑玉琢趺。","乐县通夕展，扆席乡南铺。","舞羽虞韶奏，包茅楚匦输。","祼将流秬鬯，箧实瘗璜瑜。","拜俯冠裳肃，周旋组绶纡。","嘉生光宇宙，纯嘏接方隅。","使者香奁出，祠官驿骑徂。","兆坛尊岳渎，列畤及豳鄜。","治即阴阳正，时应水旱无。","纷纭脩贡篚，容易弃关繻。","价重连城璧，雄夸照乘珠。","祥麟郊薮兽，神骏渥洼驹。","航海期王会，通城乐赐酺。","异材徵楚晋，良锻产锟铻。","户版三年计，农田九谷需。","经邦平赋敛，充府别精粗。","势迈唐中叶，功高汉两都。","皇猷垂后则，祖宪重前模。","接迹风云会，迎恩雨露衢。","春旂标禁卫，晓箭递宫壶。","班序崇鸳鹭，华裾贱貉㺄。","阁中群玉署，殿外执金吾。","馔启黄羊圈，香浮白兽炉。","宫腰齐窈窕，官瓮杂醍醐。","鲜脍银丝脆，驼峰翠釜腴。","芳馐调芍药，珍鼎荐淳毋。","优戏停丝竹，殊音备越胡。","柳塘朝潋滟，花坞夕模糊。","酬酢频倾倒，绸缪极燕娱。","时方登俊乂，人自屏奸谀。","济济星辰履，茫茫造化枢。","词场尊贾马，艺苑薄杨卢。","大雅风仍朴，群黎俗不渝。","栖岩思矫首，报国誓捐躯。","丕显传千载，重光耀八区。","封功登泰华，铭刻到衡巫。","可谓巍巍矣，真能郁郁乎。","丘园思孔孟，耕钓慕唐虞。","立德期深造，从心矩弗踰。","承家思绍述，笃学谨须臾。","忠欲绳芳躅，身惟养硕肤。","简编时讲受，菽水日欢愉。","气郁丰城剑，风留渤海桴。","夕歌樵涧谷，晨耒稼泥涂。","不效微生直，难从荷蒉逋。","陈诗堪作颂，拟赋漫操觚。","众已趋时进，吾犹待价沽。","摅忠遭盛际，诹吉奋长途。"]},{"t":"予有京师之役十月三日诸君子祖饯章江门行舟阻南征军士未发对景书怀以答厚意","f":"五言古诗","c":["城郭寒空迥，舟航晚景移。","故人从此别，对酒忍相离。","漠漠孤灯远，依依去棹迟。","碧天新月夕，红树乱云时。","灯火渔家市，钲铙虎士旗。","近闻炎海变，颇觉羽书驰。","云鸟初成阵，戈船不失期。","万方真混一，独立尚愚痴。","不杀遵神武，深仁仰圣慈。","朝廷方有道，雨露自无私。","历数千年会，冠裳万国仪。","元勋虽若猬，道脉仅如丝。","社稷斯民寄，经纶实尔资。","春袍金错凤，朝佩玉横螭。","未抗匡时疏，宁论喻蜀辞。","转输何恻恻，刀剑漫差差。","自信无遗算，谁知有我师。","物情何惨切，治道尚磷缁。","疏懒忘身拙，苍茫望国思。","祇惭岩穴陋，岂是庙廊姿。","公等俱称杰，吾徒漫欲为。","龙纹尘未拂，豹隐雾初披。","菽粟心犹淡，松筠晚更宜。","吁谟求稷契，礼乐讲皋夔。","祖训须垂后，皇猷慎所持。","未能期共达，何以报先施。","踏雪燕台上，看云野水湄。","致君心惨惨，望远目■■。","奎壁中台动，搜罗四海遗。","回春端可待，藏器又何疑。","颖颖囊锥脱，温温璞玉奇。","盍簪求旧德，倾盖结新知。","白雪终难和，青山且自颐。","临分勿洒泪，努力各相规。"]},{"t":"浦江郑氏义门","f":"五言古诗","c":["故国衣冠地，名家孝义门。","同居今九叶，袭德又诸孙。","时荐严宗祏，晨参列弟昆。","周旋俱典则，辞气总清温。","里闬尊儒素，闺门戒妇言。","承颜惟岂弟，服礼自朝昏。","籍甚群公誉，猗欤薄俗敦。","邻饥赒粟布，客至馈牢飧。","置驿遗风旧，传经古意存。","夜灯书满屋，秋气稻连村。","褒奏归廷议，桓楹表国恩。","后人方食报，逸翮蔼高鶱。","从此公侯复，终期福祉蕃。","五云来岳凤，六月起溟鹍。"]},{"t":"送丁太初温州蒙古字学正","f":"五言古诗","c":["国字崇当代，人才起妙年。","风云千里骏，日月九重天。","翰苑司抡选，中书属次铨。","光荣毛义檄，奋发祖生鞭。","学广儒宫制，书传弟子员。","宦情依冷椽，官舍拥寒毡。","筮仕无踰此，如君更颖然。","永嘉今壮辟，多艺夙称贤。","咨访兼留意，英髦孰接肩。","旧家疑寂寞，遗简想流传。","必使声华盛，应知学业全。","高情何特达，胜日共周旋。","荐豆登霜柚，充庖载海鲜。","洞箫吹月下，玉树立风前。","已兆鱼龙化，何嫌雨露偏。","群公争荐进，拭目去翩翩。"]},{"t":"题丁县令祷雨记后","f":"五言古诗","c":["方夏时苗盛，恒阳岁事愆。","皇皇良宰念，秩秩祷祠虔。","牲币修群祀，旌幢拥列仙。","幽穿青涧底，危陟白云颠。","清庙神来只，瑶台夜肃然。","月生丹井露，雾湿石炉烟。","肸蚃期真贶，精诚彻邈玄。","蛟龙盘窟宅，圭璧达渊泉。","甘澍随车至，灵飙卷旆旋。","为霖因往日，行潦及前川。","吏治能无愧，农功屡有年。","弦歌春蔼蔼，民物思绵绵。","已觉讴吟溢，惟令翰墨传。","昔贤曾志喜，太史续雄篇。"]},{"t":"趋京道逢刘簿赋诗赠之","f":"五言古诗","c":["好山青拥县，咫尺野人居。","佐政纡才杰，承流畏简书。","仙凫飞向日，瑞鹤远随车。","家自簪缨盛，心犹玉雪如。","丰姿瞻岂弟，马迹历崎岖。","光接郎官宿，声传禁直胪。","茅茨驯燕雀，山泽老樵渔。","倾盖论交晚，维舟上国初。","广输河润远，沾溉晋波馀。","对酒春生坐，调琴月满除。","云开龙影动，江阔雁行疏。","别后能相忆，裁书为起予。"]},{"t":"守冻徐州腊月八日大雪与贰守秦侯及同馆生联句侯许携酒共赏违期不至遂拾馀韵以赋残雪凡联句已用者置不取","f":"曲","c":["故国徐城壮，崇台楚骑骁。","豪华虽寂寂，名物尚翘翘。","游士宾王日，群农祭腊朝。","冻流胶舴艋，寒木寄鹪鹩。","三尺冬堪瑞，经旬气未销。","太平还有象，景色苦相撩。","发耀因明月，凝威借怒飙。","深藏寻隐曲，厚积上嶕峣。","阴瓦千塍玉，珍瓷六合窑。","中规仍毁璧，鋈槁尚敷镣。","向日潜生魄，迎曛颇沃焦。","危峰明带缟，疏柳弱垂髫。","甸壤疑翻卤，堂皇讶长硝。","丱银坚出冶，灰蜃盛涂?。","委壑终含垢，流澌始觉熇。","时和调玉烛，阳律长葭萧。","秋思抽梁赋，民情慕角招。","休徵自有瑞，纯嘏贵能徼。","同乐期重赏，赓歌视不佻。","履穿东郭倩，舄赐尚方乔。","旅馆时操翰，华裾每驻镳。","饮倾金错落，醉拂锦妖娆。","逸思翀霄鹤，羁情在鞲雕。","危言能有采，庶不愧刍荛。"]},{"t":"河西李氏孝义旌门","f":"五言古诗","c":["邦人推厚德，天语表高门。","自昔干戈集，于今孝友敦。","振振生八世，蛰蛰又诸孙。","世已朱轮贵，颜如白玉温。","承家深雨露，制行谨朝昏。","粟麦千夫膳，牛羊几处村。","联翩来汗马，奋激起溟鹍。","家法常如此，官资讵足论。","一经遗教在，百忍古风存。","棣萼荣春服，荆花覆酒尊。","羽仪鸿有序，兵卫虎连屯。","盛事垂编简，声华彻禁阍。","恩波通弱水，和气接昆崙。","薄俗嗟沦靡，陈诗示后昆。"]},{"t":"彭城守春旱祷雨","f":"五言古诗","c":["恒阳徵僣忒，云汉闵时劳。","大野黄尘动，中街白日高。","穷黎忧恻恻，良牧思忉忉。","礼秩祠群望，官联领众曹。","雩坛登祝史，俎实载牲牢。","肸蚃通幽閟，精诚绝慢慆。","王春方介祉，神化岂屯膏。","灵雨随车骑，阴风卷旆旄。","麦禾朝娓娓，松桧夜骚骚。","甘泽经三日，浑流失九皋。","涓涓通陇亩，衮衮向波涛。","陋巷荒蛙黾，衡门拥艾蒿。","杂花红似锦，细草绿于袍。","已识天无妄，宁论地不毛。","秋成看栗栗，民食免嗷嗷。","帝德回衷眷，舆情解郁陶。","巫歌迎赛肉，社鼓送香醪。","岂弟皇恩畅，循良盛世遭。","书年应纪异，作颂更兴褒。","亦有垂纶客，临流为洒毫。"]},{"t":"送翟御史佥山北宪","f":"五言古诗","c":["北京开臬府，持节肃群工。","宠甚郎官幕，威仍御史骢。","承恩方踖踖，辞阙去匆匆。","紫气榆关外，朱轓瀚海东。","霜寒翻鸷鸟，云影送冥鸿。","观省穷辽水，从容问国风。","宸衷推恻隐，庙议动昭融。","已觉皇威布，常令主泽通。","边烽无野战，物色屡年丰。","善政应除弊，贞心独秉忠。","祀朝依碣石，宾日候王宫。","处处讴歌起，家家乐事同。","勋名宜立致，簪绂会登崇。","更草匡时疏，慇勤达帝聪。"]},{"t":"六月二十日奉迎皇太子宝章龚左司赋诗遂次其韵","f":"五言古诗","c":["万世尊皇极，重光启帝猷。","草仪周典礼，特笔鲁春秋。","鹤驾高门出，龙章别殿收。","承祧称主器，监国赞成谋。","旭景前星焕，春宫御气浮。","辇前新蔟仗，花外不闻驺。","甲观三千里，霓旌五色斿。","珊珊苍玉佩，穆穆翠云裘。","定命迎仙荚，祯符锡范畴。","龙媒初效力，雁序总停辀。","宿雨犹涵润，凉风飒似秋。","九重思继述，四海念怀柔。","自昔经纶密，应知德业优。","朝宗脩贡篚，画一接康侯。","燀赫张天步，从容仰冕旒。","穆生存醴久，疏傅锡金稠。","问学虚前席，登瀛列旧游。","国惟隆本干，时已播恩休。","亦有樗材散，宁无匠石求。","濡毫虽儗颂，健笔愧难俦。"]},{"t":"上命师相辅导青宫又次前韵","f":"五言古诗","c":["黄阁资贤辅，青宫赞圣猷。","潜龙渊肃肃，仪凤羽秋秋。","秘殿黄金额，仙居白玉楼。","台阶基化运，后德顺嘉谋。","昭代功无敌，高名世不浮。","衣冠陪后骑，貔虎拥前驺。","庶事犹悬鉴，群公若缀斿。","醉传鹦鹉盏，寒赐鹔鹴裘。","宿漕风连海，新田雨满畴。","捷书时插羽，使者日乘辀。","阀阅经纶地，明良际会秋。","圣情归锡赉，天语出温柔。","固识王章在，深惟相业优。","河山留誓劵，茅土冠君侯。","越骑瞻戎服，徐邦识庙旒。","法从三尺谨，恩及万方稠。","薄艺尝簪笔，微班得从游。","未能酬夙志，何以报鸿休。","钟鼎非吾愿，山林亦易求。","寸衷徒耿耿，期与古人俦。"]},{"t":"辛巳秋初归田有期喜而成咏因感今怀昔赋成一百五十韵","f":"五言古诗","c":["河山神禹绩，幽冀帝尧都。","畿甸三千里，干城百万夫。","天戈随所指，地轴待人扶。","迹启龙廷远，兵临虎塞孤。","群雄归霸主，四杰翊基图。","炎绪宾旸谷，寒金抚锻炉。","中原方板荡，庶类划昭苏。","九壤邦家赋，三农黍稷租。","户封登岁版，物贡应时需。","漕转河仓腐，烟输甸灶餔。","经纶开世室，混合尽寰区。","弼亮求耕钓，英贤起贩屠。","有桥题墨柱，载道弃关繻。","济济皇多士，雍雍国硕儒。","师行汤誓训，谟协舜都俞。","一德遵神武，多方囿化枢。","星辰天北极，文物地东隅。","孺子谁堪托，交邻信已渝。","祸机生肘腋，剥丧切肌肤。","内溃离荆楚，先声震越吴。","筑台方拜将，破竹已长驱。","谈笑收图籍，轮囷发藏帑。","义夫思感激，烈士涕沾濡。","旌旆沧溟棹，衣冠岛屿郛。","哭秦无复报，蹈海竟何辜。","曾记忠臣传，空存内秘厨。","始因三统正，巳作万邦孚。","重译而来献，脩程不惮劬。","建邦强本干，分社列茅蒩。","绶冕朝仪集，梯航贡篚输。","殿开金幕席，地隐锦氍毹。","率土尊元会，灵杓直孟陬。","垂旒容穆穆，鸣玉色愉愉。","瑞拟龟陈范，祥开象载瑜。","凤旂飞黻绘，虎帐插彤玈。","昼接初张宴，春城大赐酺。","舞行分羽翿，乐奏引笙竽。","御酒擎鹦鹉，宫腰蹋鹧鸪。","绣帘香喷雾，红袖脸凝酥。","宠锡公无诐，皇心爱不姑。","从容周典礼，宏远汉规模。","勋业诚高矣，文章亦焕乎。","堪舆全所畀，开辟古来无。","奕世归前烈，丕承仰圣谟。","设科仍较艺，献颂竞操觚。","第列金张密，恩从卫霍殊。","锡符盟劵赤，纳陛戟门朱。","优戏时闻鼓，珍庖日荐腴。","花娇金屋贮，葧熟翠眉须。","擅制由先彻，承谋又故吾。","豪胥真首祸，接迹合群谀。","豺遘多嚵嚼，蝇营善嗫嚅。","程书违尺度，黩货较锱铢。","鼎餗顷筐载，宫墙粪土圬。","纷纷联组绶，琐琐进葭莩。","编户渝名籍，枢兵窜隶奴。","赋输年削弱，魑魅暗揶揄。","廊庙轻千虑，锄耰起一呼。","蚁穿终溃决，蛊食莫支吾。","伏莽狺狺犬，鸣祠处处狐。","邑荒烟寂历，野战血模糊。","国步何颠踬，奸谋敢觊觎。","风尘朝漠漠，笳管夜呜呜。","烽燧飞燕蓟，冰澌带易滹。","楼前朱汗马，城上白头乌。","奚啻生疵疠，畴能洗毒痡。","赐书从慰藉，哀诏漫于戏。","怅望鸿飞阔，追扳骥足驽。","射天悲溅血，浮海勇乘桴。","迷复行多眚，颠頣口卒瘏。","人才今卤莽，世道日榛芜。","忆昔丘园贲，怀贤岁月徂。","紫微华盖坐，黄道泰阶符。","乔岳宗衡岱，深源达泗洙。","作人宜棫朴，为政敏蒲卢。","国已称多造，时方见大巫。","共稽夔乐律，独咏鲁风雩。","石室紬书盛，宾筵讲席敷。","百年悲宰木，一束奠生刍。","子敬家毡在，元成世业俱。","六经悬日月，百刻谨朝晡。","力学为师古，专门亦授徒。","许身期稷禹，忧世慕唐虞。","自忝龙门客，人称凤穴雏。","让推吴季札，忠拟斗于菟。","官政年方盛，成均矩不踰。","于焉思继绍，不敢离须臾。","粉署青丝直，华堂瑞锦铺。","清时叨著作，极力事描摹。","述德安能伋，知非窃比蘧。","苍茫怀野服，容易接亨衢。","清庙资梁栋，微材愧欂栌。","立螭簪白笔，冠豸伏青蒲。","折槛心常壮，牵裾气不粗。","家声幸未坠，朝论转相揄。","鱼橐垂腰重，驼章结绶纡。","乘舆时警跸，琐闼晓追趋。","赐食分羔雉，连茵杂豹貙。","上林巢鸑鷟，太液散鸥凫。","春色红云岛，寒光白玉壶。","暑清长夏簟，露浥冷秋菰。","宫树惟栽柳，仙家亦种榆。","步陪宗伯履，筵列侍中襦。","服礼期无玷，论兵实自迂。","承恩辞殿陛，列骑出闉阇。","上日群公饯，皇华六辔诹。","宣威扬绣节，伐叛赐金鈇。","霜气横埤堄，湖光应属镂。","由来怀德地，今日不臣诛。","否泰机潜伏，乾坤乱已怃。","侯王神所赉，僣窃尔何愚。","优诏从宽大，伤心献馘俘。","辕门存简翰，斥候遣戈殳。","小腆原原附，渠魁寸寸刳。","临危亲决战，鼓勇誓捐躯。","分阃多违命，争权始搆诬。","漫遭摇毒虿，岂望报恩珠。","谁谓青蝇集，能令白璧污。","山昏鹗啄屋，江暗雁衔芦。","暂铩扶摇翮，真成局促驹。","藩臣隳戎备，野老独惊吁。","蔽日来幡帜，长风送舳舻。","闭关方吝赏，破的已摧枯。","举目郊原窜，传声将相逋。","与谁矜阀阅，无复顾妻孥。","殷冔怜崩角，豳歌美跋胡。","居然鱼漏网，拙甚雉罹罦。","戴笠山头杜，持旄海上苏。","悽悽冰肺腑，飒飒雪头颅。","夔蜀诗千首，嵩阳饭一盂。","满盘朝苜蓿，几见岁屠苏。","义路成孤往，名缰讵可拘。","民情眉可察，羁思口空糊。","枕石身长病，餐霞体任臞。","秋原伤蔓草，夙志弃桑弧。","未筑扬雄宅，犹乘范蠡湖。","感时思顾遇，望远意踟蹰。","故里荒松菊，良田秀堇荼。","舆台夸负乘，衿佩困泥涂。","林黑烟藏豹，山空雨笑鼯。","仰天瞻大介，无地哭穷途。","茅屋寻常梦，梅花八九株。","败垣牵薜荔，流水插粳稌。","野蔌从人馔，村醪不用沽。","春风徐步屧，秋影鉴髭须。","麋鹿忘猜隙，渔樵结友于。","独招华表鹤，亲钓锦江鲈。","溪月明如昨，山花色似姝。","经丘通窈窕，寻壑历崎岖。","真似陶彭泽，归来足自娱。"]},{"t":"归舟江涨","f":"五言古诗","c":["乾坤谁草昧，城郭自戎衣。","白发频年病，沧江此日归。","长途经战斗，久雨滞芳菲。","云水浮天起，风帆逆浪飞。","寻盟鸥泛泛，尺素雁依依。","汨没声名在，艰危故旧稀。","及春营野事，诹吉到荆扉。","红杏家家酒，青山处处薇。","节旄寒更落，遁迹气常肥。","不洒前忧泪，惟全杜德机。"]},{"t":"次韵归途示友","f":"五言古诗","c":["仙舟杨柳渚，游子芰荷衣。","剑引龙光动，樯随燕语归。","莺花春冉冉，烟草暮菲菲。","北极枢常运，南风檄屡飞。","曹瞒空有挟，刘表竟谁依。","高卧风流远，诸生候问稀。","久无沧海梦，自掩白云扉。","遗事曾编竹，幽情独采薇。","乘时生蠹孽，遂欲饫膏肥。","泉石无乖愿，风尘早息机。"]},{"t":"吴原庙龙津亭","f":"五言古诗","c":["龙德为天用，神功发地灵。","风行千里雨，气合两池星。","肸蚃通幽閟，昭融接混冥。","朝廷崇祀典，郡国载图经。","阖辟乾坤大，高深海岳宁。","祈禳端有自，黍稷肃惟馨。","古庙丹青画，威颜土木形。","红尘生澒洞，碧瓦见飘零。","野甸寒芜白，高原老树青。","江山馀胜概，党术有津亭。","望远云三岛，凭虚屋四楹。","衣冠存古制，翰墨表仪形。","珠浦光仍复，绡人织未停。","远孙来拜俯，遗事系瞻听。","志已期增饰，谁能与勒铭。","南阳吾独卧，西岭亦高扃。","不作南岩梦，难招楚泽醒。","题诗寄寥廓，感慨在郊坰。"]},{"t":"再和康武一百五十韵","f":"曲","c":["临川真隐处，华盖古仙都。","拔地几千仞，当关惟一夫。","堪舆方镇立，开辟鬼神扶。","秀色金莲并，晴天玉笋孤。","龟畴标分野，鳌极奠舆图。","蜕迹仍留洞，遗丹尚在炉。","寿星南斗迥，氛瘴北风苏。","涧草俱灵药，畬田亦国租。","土宜兼沮洳，物贡备供需。","石乳晨堪采，霞浆夕待餔。","昔时存庙殿，大谷有廛区。","福祉民依德，齐民市绝屠。","多方真合统，九达不传繻。","世业因成俗，山居半是儒。","代祠天使下，赐号帝音俞。","六宗分坛兆，三辰运道枢。","休嘉垂胤祚，纯嘏浃边隅。","大化能无诐，群情孰敢渝。","空花光夺眼，寒粟冻生肤。","建礼师从蜀，逃名卒在吴。","诗传山鬼咏，酒噀泽龙驱。","玄璧加神币，香奁发御帑。","菲菲空翠扑，滟滟露华濡。","架壑虚撑屋，悬崖俨甃郛。","四方牲制副，百物礼称辜。","圆煇升朝气，天灯映夜厨。","便蕃真贶集，容易惠心孚。","禳禬邦家谨，跻攀守牧劬。","登歌丝间竹，缩酌馆承菹。","象物委蛇致，精诚恳款输。","周旋瞻肸蚃，拜俯藉氍毹。","震电惊岩隙，暾阳眺海陬。","洋洋群望秩，穆穆万灵愉。","云干铜池秀，瑶花雪色瑜。","高居朝绛节，大纛拥弓玈。","雅颂农迎腊，春秋党醵酺。","萍甘分楚实，松响效齐竽。","阴谷藏?蜼，阳坡叫鹧鸪。","远岚浓似黛，小雨润如酥。","羽札传青鸟，鸾书降紫姑。","卑高归育发，陶冶出钧模。","神化茫茫尔，文章郁郁乎。","坤维终古在，国事近来无。","不有氓为祟，乌知庙失谟。","妖尘徒澒洞，秋色自棱觚。","和顺英华畅，生成品汇殊。","叶重光点漆，果熟艳施朱。","春尽薇尤脆，秋来蕨更腴。","衣冠惊俶扰，物色静相须。","专壑深连干，趋朝一远吾。","官联陪俊杰，史笔削奸谀。","陈谊惟忠蹇，摛词岂嗫嚅。","太阿初失柄，关石竟迷铢。","所限千寻抺，空怜一篑圬。","烽烟历江海，玉树倚葭莩。","旧业馀兵燹，新诗示獠奴。","昭融生掩抑，罔两肆揶揄。","逸志终难降，高飞不易呼。","含情问桑梓，忍泪盻楸梧。","废邑号豺虎，荒墟穴鼠狐。","归心寒怵慄，望眼老模糊。","佌佌争沦没，蚩蚩窃觊觎。","战场犹斗格，暴气独喑呜。","盆子空怀沛，王郎不渡滹。","久传河上骑，应逐幕中乌。","潦倒怜身病，艰危念主痡。","风云增契阔，纶綍息于戏。","己觉归迟暮，何由策蹇驽。","尘侵蓬岛树，浪蹴海津桴。","问俗情怀恶，营巢手足劬。","闾阎忘揖让，松菊尽荒芜。","帝业元无外，先朝事己徂。","万邦归显烈，一德閟阴符。","道统承周旦，儒声谒鲁洙。","词华高汉魏，翰墨劣王卢。","大雅兼商颂，悲歌出楚巫。","祝传多福告，祠报有年雩。","允迪重华协，祗承四海敷。","大宾朝玉帛，厚往及薪刍。","间出生人杰，由来盛际俱。","降神资屏翰，立德继申甫。","不识真王佐，犹知大圣徒。","经存遗礼乐，书正古唐虞。","户屦来朋乐，家毡付众雏。","宅中思卜洛，丘首欲营菟。","耋齿能无倦，从心自不踰。","业弘天广大，熙缉道须臾。","帝制频繁掌，皇文特达铺。","应期俱述作，好古岂临摹。","命世人推孟，时言使托蘧。","悠悠怀道迹，坦坦履高衢。","清庙朱弦瑟，明堂藻绘栌。","穷年遗寝榻，终日坐团蒲。","大匠宜规矩，群材合细粗。","缙绅蕲荐达，悬鉴发褒揄。","楚楚长裾曳，锵锵弱组纡。","经筵重席讲，家礼过庭趋。","旭序班鹓鹭，星垣列虎貙。","共瞻仪世凤，暂出上方凫。","芍药分珍馔，伊蒲送玉厨。","好贤旋授粲，调鼎或宜菰。","车马阴阴柳，星辰历历榆。","成均馨羽籥，公子锦衣襦。","鼓铎明彝教，章逢化腐迂。","一朝违观阙，孤棹别城阇。","几见宣麻召，频来驷马诹。","游山时着屐，刊径晓持鈇。","袤障扬旌旆，平冈按属镂。","亭台迎客赏，榛?命童诛。","气合天无际，秋明势更虚。","孤高来爽豁，阻塞肖昏愚。","培埴还依麓，牵连若献嵎。","周回青屏翳，罗立碧戈殳。","几度凌巇崄，谁能与刬刳。","敝庐千载契，高卧百年躯。","候气常闻异，嘉祯讵可诬。","白虹开楚璞，明月并隋珠。","早已高时望，乡无旧染污。","出门平陟巘，临水密编芦。","差谷雍雍雁，场苗皎皎驹。","遗荣恒淡薄，勇退众惊吁。","采服从龆龀，青帆共舳舻。","鹤归华表远，龙去石池枯。","今似秦人赘，长怜楚客逋。","无家怀里巷，有恨哭妻孥。","抔土阨山怪，归魂依舶胡。","区区近骨月，稍稍脱罿罦。","遗恨贤王李，甘心属国苏。","扶藜劳胫脰，览镜愧头颅。","春麦黄云杵，秋粳白雪盂。","比乡仍枳棘，何处又屠苏。","夙契留深眷，羁怀耿自拘。","草冠心寡累，藜糁口堪糊。","胜地蒙招隐，高情欲养臞。","衰年常伏枕，新月屡张弧。","名阜同千里，扁舟异五湖。","望云情缱绻，触暑足踌躇。","霜脆深泥芋，饴甘沃壤荼。","诚能结茅屋，不复梦轩涂。","水国寒生燐，烟村夜听鼯。","两山元共姓，一致岂殊途。","桃是玄都种，桤宜锦里株。","瓜红秋熟速，瓮白岁收徐。","久已安时弃，何须待贾沽。","御冬存短褐，传信赖长须。","快觌期追琢，嘉言别易于。","寻盟言鸥鹭，馀事托莼鲈。","发兴成酬唱，忘形效丑姝。","天逵瞻窅窕，贤路慨崎岖。","但遂烟霞志，青山任所娱。"]},{"t":"康宗武和廉介","f":"五言古诗","c":["鳌极分群类，鸿灵奠八区。","人文疏地秘，吾道斡天枢。","羲画龙图衍，苍书鸟迹纡。","力田初识耒，伐叛肇弯弧。","穆穆隆皇治，雍雍阐帝符。","比封侯稷契，执艺总斨殳。","熙洽均黎庶，光华薄海隅。","百王宗令德，一视效宏模。","河洛滔滔水，邦畿坦坦途。","征苗开誓命，载亳徯来苏。","垂统将千祀，偕行慨独夫。","鸣岐争睹凤，流屋喜瞻乌。","文德重华并，声名二代踰。","耄荒寻遇满，板荡适遭胡。","地启耄王裔，天开素主徒。","象尼神已降，铭鼎口先糊。","礼乐昭云汉，春秋凛钺鈇。","迟回思徇铎，浩荡欲浮桴。","窈窈诗书囿，巍巍道德陬。","奠楹双涕泪，锡诔一于戏。","鲁道沦衰薄，秦坑肆毒痡。","叔孙仪卤莽，伏氏语含糊。","六艺多狼籍，群言竟嗫嚅。","隋儒轻儗议，晋帖巧临摹。","湘水迷荃芷，梧台杂瑾瑜。","书林秋淅沥，义圃晚荒芜。","京洛乾坤辟，周程剑佩俱。","道存康节邵，学衍紫阳朱。","地望崇邹鲁，渊源接泗洙。","耕莘伊尹聘，出昼孟轲迂。","寂寞遗经笥，凄凉大冶炉。","辉辉山蕴玉，蔼蔼泽藏珠。","一统真元会，群生德泽濡。","梯航千里贡，玉帛万邦趋。","绣绘衣裳被，章程典册敷。","席重丹扆座，土列白茅蒩。","盛德跻平世，频年赐大酺。","倦扶筇竹杖，寒拥罽宾毹。"]},{"t":"岁晏","f":"五言律诗","c":["空江岁年晏，暮色冰霜剧。","鸿飞何冥冥，几月度砂碛。","孤臣欲洒血，万里书一尺。","君王彀雕弓，幸向上林射。"]},{"t":"明皇教笛歌","f":"七言古诗","c":["绿杨烟袅春昼长，沉香亭北万花香。","君王制得清平曲，教与花前吹凤凰。","玉靥生霞春梦起，閒愁不上蛾眉里。","欲使娇声发绛唇，为调新谱传纤指。","绝世曾闻玉树歌，调成新曲更情多。","人间吹作无穷怨，白日深宫奈乐何。","曲中更奏霓裳舞，谁信渔阳有鼙鼓。","骊山宫树起秋风，肠断香消马嵬土。"]},{"t":"赠太虚子长歌","f":"曲","c":["昔遇太虚子，飘飘在滦京。","东风吹雪添河冰，宫树五月无流莺。","君随挂席穷彭蠡，予亦函香窥海水。","谁料宫袍又缚身，却骑黄鹤上星辰。","峨峨瀛洲客，尽是谪仙人。","从此相逢金阙下，诗酒清狂转潇洒。","扬雄闭户草玄经，白发秋来漫盈把。","矫首望太清，妙运无时停。","窅尔元化枢，历历日与星。","游尘杂氛起寻丈，容光扰扰纷成象。","所以太古仙，倒景霄汉上。","知君深居勘大还，呼吸沆瀣怡芳颜，朝衣早挂松萝间。","坐邀王子晋，吹笙紫云间，令人可望不可攀。"]},{"t":"达彦脩秘监号云松隐者又自作图邀予赋之","f":"七言律诗","c":["香垆云气半空赤，千尺长松倚青碧。","谪仙去矣秀色留，谁与孤云共栖息。","蓬莱高人业嗜古，身在道山天咫尺。","为君先约彭泽翁，五老峰前候飞舄。"]},{"t":"题燕人雪溪图","f":"七言律诗","c":["朔风惊沙大地裂，水腹冻坚飞积雪。","谁识山阴放棹时，疏竹寒梅映清冽。","鉴湖一曲绿生衣，萧萧白发苦思归。","怜君岁晏如相访，江上渔蓑在钓矶。"]},{"t":"送吴景尹游嵩岱兼寄尚元素刘道源","f":"曲","c":["尹也我同姓，论交每忘年。","闭户读诗书，所勖在古先。","男儿生时蓬矢六，壮岁何为守穷谷。","昨者张帆向顺风，千里长淮春水绿。","我闻君行不忍别，杨柳新条未堪折。","君今别我归何时，思君惟对芙蓉月。","芙蓉山月四时圆，擘崖飞瀑写哀弦。","君登嵩岱望海日，我正独坐对月听潺湲。","太室山人尚处士，昔年宦学来南楚。","刘郎好古也自贤，为访于今读书所。","缘云更有最高峰，云间倘遇采芝翁。","殷勤幸道余心忡，江南春风花正红。","有酒满盏浇君胸，酒盏有尽别意无终穷。"]},{"t":"美赵侯祈祷","f":"七言古诗","c":["徐关古郡雄东国，河上孤城高岌岌。","长波激浪两流合，远黛凝烟众峰立。","当时豪杰虽已矣，功利至今存霸习。","自从圣代百年来，稍有弦歌事沿袭。","赵侯作牧驾朝骖，紫绶银章光熠熠。","尘上彤管书牒稀，春满青郊民俗辑。","今年恒阴若为沴，满耳秋声风雨急。","惊雷怒电白日飞，拥树连村黑云湿。","旷野悲号麋鹿群，寒潭翻动蛟龙蛰。","波涛滚滚迷冈阜，禾黍离离失原隰。","天高地厚叫不闻，老农祗抱锄犁泣。","我侯输诚吁彼苍，奠币陈牲劳汲汲。","乾端坤倪豁呈露，雾散烟收倏呼吸。","丽日昭回昼景舒，祥飙荡拂淫威翕。","于今报祀礼无违，长愿丰穰民乃粒。","万井桑麻接境多，四方冠盖如云集。","侯家自是国桢干，在昔声华蔼都邑。","矢诗为载尔农谣，卷阿更续生民什。"]},{"t":"诗庄","f":"曲","c":["诗人自昔身多穷，云是身穷诗乃工。","太白飘零一杯酒，杜陵茅屋随秋风。","君庄采菽不盈掬，仅有新诗千万幅。","饥来一字不堪煮，犹是逢人索珠玉。","年少执戟称卫郎，软裘快马双明珰。","驱驰玉事出奉诏，西拂弱水东扶桑。","龙光南去冲牛斗，含香曾到扶胥口。","云边晓挂洞庭帆，花时夜醉长沙酒。","人间曾见墨淋漓，当时采笔生光辉。","千金散尽不自惜，囊中惟喜有新诗。","嗟予岂是能吟者，秋月春花浑漫写。","故园菊松已荒芜，两鬓萧萧雪盈把。","君不见相如作赋家四壁，子云草玄宅一区。","君庄风月固有馀，不知身世贫何如。"]},{"t":"段应奉湖山旧隐","f":"七言律诗","c":["临平湖边秋阁小，古木幽篁通窅窕。","云间返照落渔帆，江上馀霞送飞鸟。","蒹葭苍苍月满矶，何日西风一棹归。","诗成沽酒切鲈脍，坐见山水涵清辉。"]},{"t":"南徐守李士宁劝农之日朝廷遣使召为大兴府尹郡人为图其事求予赋诗以记","f":"七言古诗","c":["晴川迟日明花柳，酒帘乐器村村有。","承平官府劝农来，竹马齐迎贤太守。","自从太守到南徐，春衣有帛食有鱼。","男耕女织不用劝，连冈断垄皆新畬。","今年又见祠田祖，牢醴香肥杂歌舞。","乌犍受策自扶犁，东风霎霎吹灵雨。","柔桑枝上啭黄鹂，树下父老相支携。","官曹抱瓮贮浓酒，移馔芳亭随所宜。","老农得饮增欢喜，起听训言书满纸。","朝廷无以我公归，坐使风移民俗美。","我公归去民何从，作图赖与奏天聪。","常遣太守如我公，我民至老歌年丰。"]},{"t":"潘子华画上京花鸟","f":"七言古诗","c":["滦阳三月雪正飞，陇树四月青红稀。","白翎啄沙黄草薄，阿蓝短翅寒相依。","南薰吹水振群蛰，满川花草浓云湿。","穹庐露冷牛马肥，蒺藜沙上西风急。","潘侯妙笔留神都，金莲紫菊谁家无。","江南莺花春冉冉，谁写当年蛱蝶图。"]},{"t":"栖鹊图","f":"曲","c":["江空月冷霜如水，双鹊梢头飞不起。","钱侯写生苦逼真，淡墨萧疏妙难似。","君不见上林高树拂云齐，托巢生子总相宜。","愿尔朝朝来报喜，春风长在万年枝。"]},{"t":"野航亭为陈晋赋","f":"七言古诗","c":["山人筑居青涧傍，数间矮屋如舟航。","清风粼粼白石烂，满目野水凝秋光。","浴水凫鹭閒来去，凭栏总是沧洲趣。","竹间凉月白纷纷，更似芦花最深处。","高情阅世犹虚舟，久矣委心从去留。","秋风不待归张翰，夜雪每疑来子猷。","儿童忽报前川涨，云雾轩窗九天上。","故园梦断酒初醒，落日遥闻采莲唱。","西安城边芳草多，乱汀横渚尽烟波。","纫兰为佩寄远道，又恐閒门无客过。","迢递江南望江北，住久岂知身是客。","多情我自爱桐乡，自信鸥盟寒不得。","亦有扁舟彭蠡宾，别却槎头今几春。","明朝便合投簪笏，向子亭边与卜邻。"]},{"t":"徐州赠同邸客","f":"七言古诗","c":["临川山人来作客，万里携书上京国。","朔风吹起黄河冰，河上行舟带寒色。","穷冬雪花三尺深，客窗抱膝惟长吟。","夜闻解鞍有同邸，晨即市酒开囊金。","举杯殷勤相为语，家在单州闾巷里。","庭闱有亲七十馀，阖家稚耋数百指。","上堂称寿春熙熙，下堂服劳日济济。","门户有子应晨昏，盘飧任妇承甘旨。","东风吹绿牛羊肥，良田自足供锄犁。","夹溪桃李炫晴昼，映阶萱草迎春辉。","共知吾邦是乐土，男勤耕桑女织组。","贸迁有货居廛市，岁时无事烦官府。","家人老大不出门，长儿近日游荆楚。","阿婶爱孙如至宝，尽室悲惊为愁苦。","予情触此更皇皇，远出求之来侍旁。","贤愚不足挂怀抱，夙夕忍此慈心伤。","我闻斯言亦感激，秉彝至德各有常。","尔能慈孝出天性，笃行自足为义方。","责善恐违贤圣训，至诚可贯金石刚。","琴瑟在御良燕喜，埙篪迭奏成雁行。","庭前綵服列三世，人生至乐乐未央。","酒酣为子歌慷慨，持赠可比黄金珰。","嗟予霜露兴惨怆，蓼莪三复劬劳章。"]},{"t":"湖西罗受可作梅月图赠予北行赋此报之","f":"曲","c":["青山湖上去，白云湖上住。","草屋八九间，梅花两三树。","年年许客看花开，花下携琴载酒来。","对花把酒唤鹤舞，酒酣落月尚衔杯。","黄昏疏影横斜好，更取生绢拈笔扫。","高情能画胜能吟，风雪荒寒忆郊岛。","我来不值花开时，骑马独从湖外归。","上阳密露春如海，祗有东家蝴蝶飞。"]},{"t":"九江丁祀闻鼓吹感怀","f":"七言古诗","c":["上丁脩祀又春分，鼓吹声传旅夜魂。","世路荆榛迷圣域，沱江烟草怨王孙。","空怜宇内干戈满，无复河间礼乐存。","上国风云清庙閟，中天日月素王尊。","春秋摄献元臣重，爵秩追崇祝号敦。","束帛承筐先俎豆，牢牲升鼎从羔豚。","公侯显相千金币，牺象宗彝九酝樽。","玉磬编钟歌大吕，朱弦疏越奏云门。","诸生襟佩趋鹓序，百辟冠裳谨骏奔。","翠积宫庭寒肃肃，光生花树晓焞焞。","秦坑灰烬遗经坠，王业陵迟古道昏。","霄翮倚风留退鹢，辙鳞随水化冥鹍。","八音夔律何由正，六典周官讵易论。","自叹白头思绍述，谩垂青简照乾坤。"]},{"t":"江上晚景图","f":"五言律诗","c":["远景峰峦色，高松铁石柯。","晚晴初放棹，春水已生波。","尽画沧洲趣，难传欸乃歌。","山居无户牖，端为白云多。"]},{"t":"紫霞庵","f":"五言律诗","c":["结茅江水上，霞气护幽居。","巳似赤城迥，常疑丹井虚。","仙桃承雨种，秋叶带霜书。","应得长生秘，晨餐愿乞馀。"]},{"t":"赠梁道者","f":"五言律诗","c":["江东梁道者，自少学神仙。","袖有烧丹术，囊无买酒钱。","看云眠白日，对月礼青天。","为问蓬莱水，何时似昔年。"]},{"t":"山居图","f":"五言律诗","c":["茅屋在林阴，桃花夹径深。","远山浑似黛，游客总能吟。","杳杳穿云杖，萧萧坐石琴。","展图怀旧隐，便欲解朝簪。"]},{"t":"六月舟次房村","f":"五言律诗","c":["红日荒荒落，黄河滚滚流。","客行当盛夏，水宿似清秋。","市远人烟少，村平树色稠。","遥山青数点，明日过徐州。"]},{"t":"极高明亭","f":"五言律诗","c":["凭虚连白水，望远俯青山。","结屋烟尘表，吟诗松竹间。","落花缘客扫，飞鸟共云还。","肯着蒲团坐，从君尽日閒。"]},{"t":"仙游观紫云亭","f":"五言律诗","c":["山色更深处，烧丹仍筑亭。","春云瞻紫气，夜月卷黄庭。","种竹堪扶老，栽松已伏苓。","何时解尘鞅，来写换鹅经。"]},{"t":"九日紫极宫对酒","f":"五言律诗","c":["野水通江阔，山云挟雨凉。","燕辞宫署远，雁过海天长。","纱帽花堪插，仙瓢酒更香。","苍茫怀国梦，烽火尚炎荒。"]},{"t":"酒罢分韵得桑字","f":"五言律诗","c":["江海舟初动，山林兴讵忘。","已荒陶令菊，未种武侯桑。","对酒云千里，怀家雁几行。","今朝小儿女，个个紫萸囊。"]},{"t":"九日夜酌分得枝字","f":"五言律诗","c":["对酒杯频举，看云席几移。","轩楹秋窅窅，灯火夜迟迟。","醉脱乌纱帽，香传白露枝。","忽思三径里，花蕊正离披。"]},{"t":"次韵答萧性渊巡检","f":"五言律诗","c":["官舍连脩竹，春旗映远山。","宦情江海外，剑气斗牛间。","田野无巡逻，渔樵有往还。","万方逢盛治，弓马更清閒。"]},{"t":"和刘季平","f":"五言律诗","c":["昔闻滩上水，远自粤南山。","乔木三春里，清音五桂间。","片云留客住，细雨棹舟还。","为恐离家久，芳庭草色閒。"]},{"t":"和萧独清","f":"五言律诗","c":["昔别是何日，长闻隐道山。","题诗传海内，卖药出人间。","林鹤随云出，潭蛟带雨还。","偶来高坐处，帘外落花閒。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其一","f":"五言律诗","c":["柳色满河堤，春沙不作泥。","家家踏青去，处处听莺啼。","翠幄凌风迥，香车簇道齐。","扬雄甘寂寞，载酒问幽栖。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其二","f":"五言律诗","c":["祠庙出东城，风云拱百灵。","神光通御阙，天影抱彤庭。","隙地多幽事，芳辰聚德星。","道人偏爱客，更许制茅亭。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其三","f":"五言律诗","c":["宫馆凭孤旷，幽林眼底生。","药畦晨露重，茶灶午风轻。","酒许麻姑送，羹从海客烹。","乡心劳想像，便欲棹舟行。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其四","f":"五言律诗","c":["新火营寒食，他乡展物华。","暧云将燕子，春色上桃花。","自进贤人酒，何劳妓女车。","平居耽野趣，未觉道林赊。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其五","f":"五言律诗","c":["圃因春雨种，竹自昔年移。","云影常依石，春泉已满池。","望中情未极，花外立多时。","每动田园兴，东风长鬓丝。"]},{"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其六","f":"五言律诗","c":["上林华盖逼，宫署紫垣开。","疏阔经时序，淹留惜酒杯。","仙人栽杏去，学士看花来。","几日应开遍，题诗许重陪。"]},{"t":"仙人游图","f":"五言律诗","c":["莺啼通窅窕，马迹历孱颜。","载酒溪桥外，哦诗松树间。","桃花深映竹，云影浅依山。","无限临流兴，扶藜欲叩关。"]},{"t":"送人归蜀","f":"五言律诗","c":["愁寂都门别，艰危蜀道行。","四山皆雨气，尝日有鹃声。","北极红云阙，西江白帝城。","怀亲兼恋禄，去住总关情。"]},{"t":"送人下第南归","f":"五言律诗","c":["落卷人争读，扁舟客自归。","苑花秋冉冉，江雨梦霏霏。","壮志经留笥，伤心线在衣。","看君负文彩，他日倍光辉。"]},{"t":"童氏作楼奉亲名曰乐心","f":"五言律诗","c":["高构日登临，庭闱总称心。","游鱼出水底，鸣鹤在林阴。","山雨晴留黛，松风夜当琴。","地幽多胜事，不惜酒频斟。"]},{"t":"史指挥作堂学傍名泮邻","f":"五言律诗","c":["旌棨将军第，今联孔子堂。","泮泉通射圃，庭草映宫墙。","义训三迁旧，家声五桂香。","城南天咫尺，驻屐许相将。"]},{"t":"送蜀士赴潮阳巡检","f":"五言律诗","c":["江深巴子国，海阔粤王城。","万里独为客，三年尝领兵。","艰危才易见，留滞气难平。","莫洒临岐泪，图南羽翮成。"]},{"t":"王孝子刲股","f":"五言律诗","c":["孝子有异行，世情生叹嗟。","炉香通夜白，股血启晨霞。","儿体应无恙，亲年幸有涯。","殷勤鄠人对，直道正奇邪。"]},{"t":"赠沛县阴阳教官","f":"五言律诗","c":["七政阴阳纪，三辰卜祝科。","中原井邑小，圣世教官多。","谯鼓夜传漏，野田春涌波。","儒冠自拘束，莫听大风歌。"]},{"t":"节妇挽诗","f":"五言律诗","c":["抱节青春苦，荥阳有故家。","教儿能绾绶，报德已宣麻。","台倚巴清墓，风传鲁妇髽。","夕阳原上树，依旧宿慈鸦。"]},{"t":"题唐子华画","f":"五言律诗","c":["老树吴江上，茅茨八九椽。","晚山浓似黛，秋水净无烟。","盘石堪垂钓，孤舟许醉眠。","卜居宜近此，何日赋归田。"]},{"t":"送毛李祥归云林因托之访予山居 其一","f":"五言律诗","c":["客子年方盛，家山花正浓。","扁舟溯鸿雁，高浪蹴鱼龙。","京国五千里，云林六七峰。","升堂举春酒，始得豁心胸。"]},{"t":"送毛李祥归云林因托之访予山居 其二","f":"五言律诗","c":["莽莽闻征鼓，纷纷踏去船。","衰颜尚簪绂，雅志自林泉。","茅屋应无恙，山田幸有年。","凭君上华盖，为访白云边。"]},{"t":"送李卓归临川","f":"五言律诗","c":["江上兵虽满，山东路已通。","发从今日白，花似去年红。","浮世嗟蓬转，幽栖想桂丛。","因君万里意，极目送飞鸿。"]},{"t":"徐氏同德堂","f":"五言律诗","c":["千载南州士，流风气谊存。","合居今五世，同德又诸昆。","白日书连屋，清秋稻满村。","圣朝敦孝礼，桓表已旌门。"]},{"t":"送杨曼卿","f":"五言律诗","c":["京国莺花里，扁舟望旧山。","烟芜连楚泽，春水隔乡关。","访古题诗遍，匡时草疏閒。","丈夫无别泪，此日满愁颜。"]},{"t":"福泉亭","f":"五言律诗","c":["筑室庐江上，山泉亦有名。","深源流福泽，长日作春声。","润借桑麻秀，寒分井谷清。","尘缨如可濯，来看白云生。"]},{"t":"挽待制杨贤可 其一","f":"五言律诗","c":["才逮古循吏，名成初制科。","百年存气节，五郡起讴歌。","致政冰衔重，题诗秀句多。","风流今已矣，洒涕望江沱。"]},{"t":"挽待制杨贤可 其二","f":"五言律诗","c":["宵旰忧民牧，人才转寂寥。","如公多令望，绝迹上清朝。","玉署真成梦，金鱼漫在腰。","庆源宜有待，嗣子各风标。"]},{"t":"送倪长卿","f":"五言律诗","c":["江汉风尘里，关河日月傍。","乍疑音问阔，顿觉羽书忙。","献赋垂归橐，销魂逐去樯。","朝缨漫羁束，何计濯沧浪。"]},{"t":"送宣使蒋槃归寄江西省郎中颜希古 其一","f":"五言律诗","c":["故国雄藩在，清秋使者归。","江湖陟险地，舟楫蹈危机。","士壮常思斗，城高屡受围。","亦尝修谏草，直欲把天衣。"]},{"t":"送宣使蒋槃归寄江西省郎中颜希古 其二","f":"五言律诗","c":["行李随秋色，萧萧出帝城。","两行忧国泪，万里望乡情。","赋敛无修贡，疮痍未息兵。","大廷俱鼎食，何以报升平。"]},{"t":"送宣使蒋槃归寄江西省郎中颜希古 其三","f":"五言律诗","c":["方镇诸军缺，城池累月攻。","战场宵燐碧，贼垒晓旗红。","幕府谋猷密，群公胆气雄。","妖氛须净扫，崖石始铭功。"]},{"t":"送宣使蒋槃归寄江西省郎中颜希古 其四","f":"五言律诗","c":["吾庐华盖下，乔木白云边。","每忆秋风鲙，常怀雪夜船。","传烽今四野，飞檄已三年。","亦有平安问，烦君万里传。"]},{"t":"送徐仁辽阳教官","f":"五言律诗","c":["辽水东临海，榆关北际燕。","官程千里外，行色五云边。","童冠来春服，歌钟杂夏弦。","莫嗟无籍在，归路近星躔。"]},{"t":"送人补闽宪译","f":"五言律诗","c":["能事通重译，宫资早致身。","江关流誉在，宪府荐书频。","雕鹗思云路，莺花怨暮春。","瓯闽边檄净，冉冉离风尘。"]},{"t":"送王都事度海入京 其一","f":"五言律诗","c":["万里皇华使，千夫瀚海船。","长风披朔雾，高浪蹴吴天。","江汉新烽燧，车书旧幅员。","不胜遗老泪，咸望太平年。"]},{"t":"送王都事度海入京 其二","f":"五言律诗","c":["便宜曾奉诏，受节大明宫。","列郡旌旗合，三关道路通。","誓师亲督战，破贼不论功。","率土王臣在，何人高谊同。"]},{"t":"送王都事度海入京 其三","f":"五言律诗","c":["许国心犹壮，驰书路更长。","物情移白黑，士气转苍黄。","郡邑风烟里，衣冠日月傍。","共谁清海岳，持以报君王。"]},{"t":"送王都事度海入京 其四","f":"五言律诗","c":["当宁资贤辅，持危巩圣图。","万邦通禹贡，九德协皋谟。","师出宜无敌，城降戒不屠。","老臣空有策，何计彻神都。"]},{"t":"望柴桑","f":"五言律诗","c":["何处柴桑里，当年处士家。","五株门外柳，九日径边花。","己草归田赋，难乘下泽车。","故山尘漠漠，极目送昏鸦。"]},{"t":"咏怀旧隐十五首 其一","f":"五言律诗","c":["旧宅今何在，云山昔更清。","樵歌秋树谷，渔网夕阳汀。","门巷来车盖，书声接户庭。","遗墟悲蔓草，浪迹信浮萍。"]},{"t":"咏怀旧隐十五首 其二","f":"五言律诗","c":["江雾仍为雨，山花故作容。","秋风馀鼠雀，寒水落鱼龙。","慷慨心犹壮，羁栖力巳慵。","白云华盖表，怅望最高峰。"]},{"t":"咏怀旧隐十五首 其三","f":"五言律诗","c":["忆昔升堂日，诸生授简时。","遗经周礼乐，野服汉威仪。","一自趋丹凤，微班侍玉螭。","风尘惊岁阔，猿鹤怨归迟。"]},{"t":"咏怀旧隐十五首 其四","f":"五言律诗","c":["高堂存古制，粹德俨先容。","道脉千年统，人心百世宗。","夜台悲化鹤，云气想犹龙。","松柏宁无恙，青山一万重。"]},{"t":"咏怀旧隐十五首 其五","f":"五言律诗","c":["西斋风月好，庭草到阶前。","春服趋童冠，秋声杂诵弦。","题诗黄叶上，拄竹白云边。","俛仰成今古，销魂为黯然。"]},{"t":"咏怀旧隐十五首 其六","f":"五言律诗","c":["乔木依深谷，居人尚几家。","衣冠迷宿草，舟楫失桃花。","转斗宁无已，劳生已有涯。","毋烦问松菊，何计事桑麻。"]},{"t":"咏怀旧隐十五首 其七","f":"五言律诗","c":["契阔风云会，栖迟道路长。","老来犹作客，春至好还乡。","酒醒天连屋，诗成草满塘。","家声尚清白，世态任炎凉。"]},{"t":"咏怀旧隐十五首 其八","f":"五言律诗","c":["党里乌巾集，邻翁古意淳。","瓶罂随野俗，耕稼及清辰。","世业诸孙在，寒山白屋贫。","为传宗谱旧，长使旅情亲。"]},{"t":"咏怀旧隐十五首 其九","f":"五言律诗","c":["幽居临水竹，老桂出林阿。","荫接青云武，花开碧玉柯。","百年秋露重，十里夜香多。","荣悴知何意，炎尘起海波。"]},{"t":"咏怀旧隐十五首 其十","f":"五言律诗","c":["故园谁识主，曝背已忘君。","雾雨鸡豚社，寒山鹿豕群。","池分涧底水，圃斸垄头云。","茅屋知堪赋，长歌对夕曛。"]},{"t":"咏怀旧隐十五首 其十一","f":"五言律诗","c":["昔人营寺日，野老在朝时。","栋宇山林净，松杉土壤宜。","海尘留法雨，檀施寄禅枝。","接地多先垄，春秋拟合祠。"]},{"t":"咏怀旧隐十五首 其十二","f":"五言律诗","c":["茅屋云犹在，桃源世已非。","渔樵能有待，鸿燕尚知归。","霜露春秋感，风尘造化机。","松楸千里日，夜夜梦魂飞。"]},{"t":"咏怀旧隐十五首 其十三","f":"五言律诗","c":["世事嗟何及，天伦恨已深。","乾坤一抔土，霜露百年心。","去住青山隔，艰危白发侵。","丈夫无别泪，此际倍沾襟。"]},{"t":"咏怀旧隐十五首 其十四","f":"五言律诗","c":["山黑天仍雪，江寒梅未花。","昔年宾国日，几醉上林霞。","勇退寻归棹，甘心理钓槎。","如何青布袜，未得踏溪沙。"]},{"t":"咏怀旧隐十五首 其十五","f":"五言律诗","c":["白社千头橘，成都八百桑。","每思亲棣萼，不为问山庄。","太史瞻凫影，家人识雁行。","茅茨容易葺，春水棹相将。"]},{"t":"匡庐","f":"五言律诗","c":["匡庐望不极，几度涉风涛。","秀色一道出，振衣千仞高。","仙岩谁种玉，鬼谷旧栽桃。","白鹤巢云表，秋宵见羽毛。"]},{"t":"双剑峰","f":"五言律诗","c":["双剑倚秋汉，孤城瞻碧岑。","岳连吴楚阔，光合斗牛深。","胜地千岩壑，长江一带襟。","州图增杀气，愁眼倦登临。"]},{"t":"述感十五首 其一","f":"五言律诗","c":["圣祖开寰宇，英贤集网罗。","暂烦周斧钺，即听舜讴歌。","世阀风云阔，耕岩雨露颇。","万方俱职贡，一旦尽烟波。"]},{"t":"述感十五首 其二","f":"五言律诗","c":["舆图归覆载，天畀万方全。","帝德元无外，皇纲自失权。","中原堕土赋，内郡落民编。","国计东南隘，经邦愧昔贤。"]},{"t":"述感十五首 其三","f":"五言律诗","c":["太祖收中夏，供储赋土田。","河仓红粟腐，漕壤紫台烟。","民物滋殷阜，车书转瘠捐。","可怜疆理在，运会付茫然。"]},{"t":"述感十五首 其四","f":"五言律诗","c":["南国昔归顺，中原仍戍藩。","岁分貔虎士，阵入鸟云屯。","名籍沦逋窜，枢兵失讨论。","诸君甘负国，故里亦空村。"]},{"t":"述感十五首 其五","f":"五言律诗","c":["帝患湮洪水，人思凿钜河。","万方劳畚锸，列郡困徵科。","处处黄巾社，纷纷赤子戈。","千年遗恨在，铭石写嵯峨。"]},{"t":"述感十五首 其六","f":"五言律诗","c":["泉货资桑币，经纶称物宜。","低昂三尺法，敛散百年规。","拙甚黄金注，凄其白鹿皮。","纷更愆祖宪，废阁失天威。"]},{"t":"述感十五首 其七","f":"五言律诗","c":["夜直麒麟殿，晨司虎豹关。","周庐诸子贵，枕戟卫郎閒。","通籍存奴隶，连车载匪颁。","世勋何补报，戎马泪潸潸。"]},{"t":"述感十五首 其八","f":"五言律诗","c":["世爵推勋阀，元戎典禁兵。","营分龙虎卫，势接凤凰城。","烽火迷千里，烟尘犯两京。","临危忘勇决，何以答升平。"]},{"t":"述感十五首 其九","f":"五言律诗","c":["黄头称国士，碧眼佩天弧。","突骑今何在，风光古所无。","旧看装宝剑，可怕执金吾。","畜锐思防患，凭谁卫两都。"]},{"t":"述感十五首 其十","f":"五言律诗","c":["命将图推爵，登坛愧匪材。","舟车空府库，金帛散舆台。","论赏屯膏泽，争权稔祸胎。","旧家零落尽，庙算实堪哀。"]},{"t":"述感十五首 其十一","f":"五言律诗","c":["四野悲龙战，群方习豹韬。","烟尘来滚滚，江汉去滔滔。","云构千章栋，风帆万斛艘。","炎波俱鼎沸，何用赋民劳。"]},{"t":"述感十五首 其十二","f":"五言律诗","c":["福极频移柄，明良久失图。","匠材违矩度，博局转枭卢。","宝鼎宗周器，玄圭大禹谟。","万方俱有间，九贡近来无。"]},{"t":"述感十五首 其十三","f":"五言律诗","c":["乳羝随敝节，帛雁识累臣。","渐觉关河壮，应瞻日月新。","威声通海岱，喜气入梁秦。","万骑轻天堑，何时一问津。"]},{"t":"述感十五首 其十四","f":"五言律诗","c":["异乡风景切，人事见推移。","冠盖非前日，豪华又几时。","年深鹦鹉草，春老杜鹃枝。","依旧青山色，寒云满目悲。"]},{"t":"述感十五首 其十五","f":"五言律诗","c":["世自馀蛇豕，人犹慕凤麟。","节旄寒在牧，鈇钺暗生尘。","有梦能归国，无邻可避秦。","几年江海上，老泪独沾巾。"]},{"t":"高卧","f":"五言律诗","c":["冰霜寒序集，灯火夜堂深。","高卧尘侵榻，长吟雪满簪。","空存三寸舌，不负百年心。","慷慨能忘死，饥寒亦易禁。"]},{"t":"初度日","f":"五言律诗","c":["衰疾年添算，劬劳思转伤。","声华江上雾，勋业鬓边霜。","诗继唐风作，书从禹穴藏。","光阴何冉冉，华盖郁苍苍。"]},{"t":"大雪","f":"五言律诗","c":["萧萧惊朔雪，浩浩怒天风。","虎穴先朝事，鹅池半夜功。","中原思将帅，乱世识英雄。","今古兴亡迹，乾坤阖辟中。"]},{"t":"相疑","f":"五言律诗","c":["向国应无计，归田屡作期。","江湖身病日，松柏岁寒时。","老鹤云千里，惊乌月一枝。","人生各有志，物态莫相疑。"]},{"t":"雪","f":"五言律诗","c":["积雪凝冬瑞，群情兆岁登。","洞门沦径隧，宫瓦失觚棱。","烟火江村猎，寒澌野水罾。","殊方兼久病，高卧竟何能。"]},{"t":"雪霁","f":"五言律诗","c":["江上千峰雪，天边几缕霞。","冻澌依岸梗，冰柱落檐花。","野回山光薄，沙明树影斜。","负暄貂已敝，抱病虱空爬。"]},{"t":"腊月朔","f":"五言律诗","c":["羁客无颁朔，穷年有此朝。","山明仍戴雪，水落不通潮。","黄道环辰极，青阳转斗杓。","仰关身万里，转壑梦连宵。"]},{"t":"世路","f":"五言律诗","c":["世路难如此，京华事若何。","风云归草昧，日月傍干戈。","南土分争久，西秦王气多。","累臣独洒泪，衰疾卧江沱。"]},{"t":"同驾","f":"五言律诗","c":["白日行天速，青山去国遥。","昔年苍水佩，同驾紫云轺。","汉节犹堪牧，虞旌不待招。","人生誇气概，莫遣旅魂销。"]},{"t":"腊日","f":"五言律诗","c":["乡心违伏腊，宦迹历关河。","酥酪分邻粥，弦匏拥醉歌。","天清云路阔，春近雪花多。","事业今如此，江边一钓蓑。"]},{"t":"戏题 其一","f":"五言律诗","c":["牧地连云水，羔羊饱杞椒。","体充香透骨，尾重雪凝膘。","珍出天厨馔，炉传禁脔烧。","先尝时有赐，况复酒频浇。"]},{"t":"戏题 其二","f":"五言律诗","c":["西域葡萄熟，浆醪不用酤。","色深滦水菊，香重塞城酥。","甘露浮银瓮，寒冰贮玉壶。","相如犹病渴，传赐近来无。"]},{"t":"闵姜公硕","f":"五言律诗","c":["窃据窥神器，人心事事非。","每闻优诏下，无复报音归。","虎穴宁容饰，龙韬未息机。","小臣徒溅血，不得沃天衣。"]},{"t":"馆人","f":"五言律诗","c":["风雪夜迢迢，探囊失敝貂。","烛龙沧海阔，帛雁上林遥。","伏枕调诗律，篝灯注酒瓢。","馆人情思厚，尚觉旅魂销。"]},{"t":"旅馆","f":"五言律诗","c":["旅馆经时序，羁愁转寂寥。","山空寒隐雾，风急夜鸣条。","塞雪应无际，军声自不骄。","何时衰老泪，拭目圣明朝。"]},{"t":"春近","f":"五言律诗","c":["颇觉边尘净，仍看昼刻添。","江风寒透屋，野日暧窥檐。","病减寻书帙，春来忆酒帘。","归心何日遂，谈笑听闾阎。"]},{"t":"积雪","f":"五言律诗","c":["积雪山河净，昏霾宇宙迷。","雁声来漠北，兵气自征西。","海雾浮龙影，关寒惬马蹄。","时危增愤结，衰病属羁栖。"]},{"t":"庐岳","f":"五言律诗","c":["庐岳不可极，山深宜养恬。","松巢邻李白，菊径似陶潜。","秀色云千仞，秋光雨一帘。","渔樵与麋鹿，於我更无嫌。"]},{"t":"阳九","f":"五言律诗","c":["厄会符阳九，沉痾阅岁三。","苏卿吟漠北，庾信赋江南。","山影开晴黛，湖光接暮岚。","艰危心不展，俯仰事何惭。"]},{"t":"春日得乡信","f":"五言律诗","c":["旅思春江上，乡山宿雾中。","鬓毛难再黑，花蕊转添红。","病减诗囊在，愁多酒盏空。","衣冠俱散走，何地哭途穷。"]},{"t":"释闷","f":"五言律诗","c":["世乱复为客，衰颜对物华。","江城年节酒，野树岁寒花。","雪岭明残照，烟汀带落霞。","为谁添白发，何计问丹砂。"]},{"t":"兵交","f":"五言律诗","c":["虎狼犹搆祸，四海苦兵交。","鼓动霜飞剑，笳鸣月拂弰。","川红依壁垒，林黑避橧巢。","野老仍羁旅，何乡可结茅。"]},{"t":"戒守","f":"五言律诗","c":["戒守时鸣鼜，传更夜击刁。","乱山青拂眼，衰柳绿垂髫。","略阵楼船壮，先锋越骑骁。","军中称汉将，谁是霍嫖姚。"]},{"t":"十有一月至于正月连雪不已","f":"五言律诗","c":["气合冰天址，光连雪岭西。","愁来望不极，诗罢思俱迷。","澌冻江淮远，昏霾岭峤齐。","饥寒春事迫，何以慰蒸黎。"]},{"t":"虚橐","f":"五言律诗","c":["世已声华改，身兼老病侵。","几年沧海梦，一旦白头吟。","旅馆惊虚橐，寒城急暮砧。","固穷知义命，何用较升沉。"]},{"t":"病中移居 其一","f":"五言律诗","c":["江水东流去，庐山北向来。","孤城新第宅，浮世旧风埃。","久病频移榻，多情数举杯。","乡心犹未已，春色苦相催。"]},{"t":"病中移居 其二","f":"五言律诗","c":["扰扰人间世，萧萧物外身。","江山如有态，草树暗生春。","自笑新巢燕，谁怜旧主贫。","旅怀相慰藉，真率见情亲。"]},{"t":"卜筑","f":"五言律诗","c":["水外十三坡，居人总荷戈。","烟营江树尽，霜木陇云多。","樵爨村村屋，斧斤旦旦柯。","白驹空谷在，何事卜行窝。"]},{"t":"战士","f":"五言律诗","c":["战士屯边垒，家人问繇爻。","寒堂悲蟋蟀，月户怨蟏蛸。","巷有招魂帛，林无返哺巢。","干戈何日洗，倒载虎皮包。"]},{"t":"烽烟","f":"五言律诗","c":["烽烟寒转急，丧乱岁难休。","野老无家别，遗畦尽力求。","关河多骑气，江海自渔舟。","世事由天运，何须涕泗流。"]},{"t":"舟中","f":"五言律诗","c":["何乡能遁迹，天地有渔翁。","沽酒时曾醉，探囊岁屡空。","衰年双鬓白，长日一丝风。","谈笑兵戈外，兴亡俛仰中。"]},{"t":"九日辛丑","f":"五言律诗","c":["两度黄花酒，尊空思转伤。","去年留病榻，今日复虚樯。","粝饭依人爨，疏衣透骨凉。","干戈天意在，去住更何乡。"]},{"t":"群情","f":"五言律诗","c":["社稷生奇变，关河入战图。","楼前朱汗马，城上白头乌。","国步分光岳，江流接蜀吴。","群情思伯业，佳气瞩皇都。"]},{"t":"所思","f":"五言律诗","c":["舆图真混一，廊庙乏才贤。","得失轻千虑，奸雄起九廛。","阴霾迷岁月，战地起风烟。","洒涕江湖外，渔舟白日眠。"]},{"t":"天意","f":"五言律诗","c":["僣窃千家郭，颠连一病夫。","虎狼相啖噬，齿爪及茕孤。","冻馁民何赖，分争霸易图。","物情知厌乱，天意启祯符。"]},{"t":"远客","f":"五言律诗","c":["远客又遘患，其如头白何。","系舟沙岸久，闭户水寒多。","喜气闻关塞，军声接汉沱。","废兴知运数，海内厌兵戈。"]},{"t":"钞掠","f":"五言律诗","c":["钞掠民何赖，孤穷痛不禁。","江山惨寒色，鸿雁有哀音。","白发三年病，青霄万里心。","路迷尘冉冉，肠断暮骎骎。"]},{"t":"孤舟","f":"五言律诗","c":["牛斗缠兵气，江湖隐使星。","客头元自白，天眼为谁青。","夕照留渔屋，寒芜接雁汀。","孤舟风水阔，百计问柴扃。"]},{"t":"悲歌","f":"五言律诗","c":["世乱人多暴，魂惊客屡过。","采薇春事远，席秸夜寒多。","凉月侵萝薜，清霜看芰荷。","荒墟唯痛哭，野老亦悲歌。"]},{"t":"子月午日壬子夜半雷雨","f":"五言律诗","c":["客愁随日度，寒律向东排。","黎庶干戈暴，苍天号令乖。","江雷宵送雨，山雾晓生霾。","安得氛埃净，春光接泰阶。"]},{"t":"徐氏园亭","f":"七言律诗","c":["河山锦绣帝城中，更辟名园在屋东。","满地绿阴三月雨，数声黄鸟百花风。","轩楹有席渔樵对，樽酒多情父老同。","逸兴已无朝市梦，相逢往往说年丰。"]},{"t":"送陈廷佐高州路教授","f":"七言律诗","c":["江州义门天下传，君今分教岛云边。","百蛮俎豆先王学，列坐弦歌弟子员。","鹦鹉园林春似海，秭归风雨夜如年。","宦情莫叹微班冷，禄米分时蚌蛤田。"]},{"t":"送归彦温河西宪使","f":"七言律诗","c":["阳关东出接西凉，皂盖朱轓陇路长。","五郡人烟无堡塞，千村部落有牛羊。","休屠庭远曾归汉，都尉城荒尚护羌。","四海舆图真浑一，祗将声教答时康。"]},{"t":"送苏伯脩由礼部侍郎赴淮东宪使","f":"七言律诗","c":["东曹礼乐竦朝端，忽奏皇华遣豸冠。","五色文章金匮富，九天风露玉壶寒。","江头画舫迎潮去，海上青山立马看。","二十四桥春似锦，飞花不到使君鞍。"]},{"t":"看云亭为慈溪匡上人赋","f":"七言律诗","c":["盘结松萝四壁空，静看云影坐从容。","风清时送归岩鹤，雨散常依在钵龙。","野水带潮微辨树，山光敛暮只闻钟。","杖藜欲去分禅榻，知隔慈溪苐几重。"]},{"t":"玉雪坡为周学士赋","f":"七言律诗","c":["曾识罗浮山下树，苍茫白石共烟萝。","几年种玉云千尺，镇日花开雪一坡。","酒熟谷中春事早，诗成湖上月明多。","青绫夜向金銮直，疏影黄昏奈尔何。"]},{"t":"丘参军妻守节","f":"七言律诗","c":["紫髯不见旧参军，桓表旌门墨色新。","云雨几时同穴梦，冰霜百岁未亡身。","香奁有泪迷鸾影，锦瑟无声落燕尘。","萱草堂前今种柏，翰林留记写精神。"]},{"t":"保定王氏母九十得赐帛乡人合燕为寿","f":"七言律诗","c":["皇家赐帛出郊圻，王母光荣九十时。","仙露酿成千日酒，春风来自万年枝。","旧颁官诰从儿贵，新制恩袍与体宜。","已是八荒开寿域，城南咫尺接天墀。"]},{"t":"送毕氏子韶州访翁李知事","f":"曲","c":["蜑雨收岚海气凉，陇船迎浪粤山长。","杜鹃乱叫杨梅熟，鹦鹉低飞荔子香。","筹幕望云依北极，琴台延月对东床。","宫岩石乳?于玉，服食应须远寄将。"]},{"t":"赋梅竹轩寄太史杨公","f":"七言律诗","c":["湖上开轩接浪波，映阶梅竹更婆娑。","润留翠黛春云合，寒入冰绡夜月多。","嘉实可供调鼎餗，长竿终自伴渔蓑。","清风三径人如玉，越水吴山奈尔何。"]},{"t":"送刘成德之京师","f":"曲","c":["玉溪杨柳绿依依，新着丹袍陟帝畿。","江上马蹄春蹀?，日边龙角晓依微。","禁墀香近神仙佩，御苑花开锦绣围。","亦欲乘槎问星使，祗愁老却故山薇。"]},{"t":"题桐木韩氏族谱","f":"七言律诗","c":["韩家相业当时重，盛德名昆集凤池。","章佩并县金错落，宣麻同拜玉淋漓。","梧桐春雨江南梦，松柏秋风海内悲。","孙子尚馀宗谱在，更传遗事后人知。"]},{"t":"杨公明徐志可贻诗次韵荅之 其一","f":"七言律诗","c":["几杖曾陪上玉京，几回听漏酒初醒。","琳琅春盍朝天佩，云母时开迎御屏。","银瓮赐馀莲子白，金鱼恩重荔枝青。","不才犹欲承先泽，樗散何堪辱在庭。"]},{"t":"杨公明徐志可贻诗次韵荅之 其二","f":"七言律诗","c":["南州榻在长留客，北海樽空未易醒。","台馆四时如锦绣，云霞长日作帷屏。","桃成秋实千年碧，橘待霜肥万颗青。","闻说临池多逸兴，笼鹅时与换黄庭。"]},{"t":"宋蕲之广济簿尉黄刚中脩水人也至元天兵渡江中十九矢而死妻刘被掠子甫十岁既长求其母凡十年知已没入官迎驾哀诉得旨使为母子如初","f":"七言律诗","c":["临危百箭忠臣血，流落孤踪孝子心。","霜露年年秋草碧，关河处处暮云深。","仰天已觉恩如海，爱日常怀泪满襟。","继述好留青史传，凄凉更赋白头吟。"]},{"t":"环青堂","f":"七言律诗","c":["黔南泉石尽烟霞，幽夐偏宜隐者家。","四坐春山有秋色，一川流水见桃花。","樵歌窈窕穿云去，眉黛婵娟对日斜。","更说官閒松菊在，芒鞋应许踏轻莎。"]},{"t":"翰林上直次周伯温韵 其一","f":"七言律诗","c":["宫庭白日静相宜，铃索无声谩自讥。","云近帘栊秋影薄，香飘殿阁晚风微。","典谟事业千年册，黼黻文章五色机。","每叹小臣怀补报，寸衷何计达宵衣。"]},{"t":"翰林上直次周伯温韵 其二","f":"七言律诗","c":["金鸭香分石鼎茶，日长宫署寂无哗。","庭前草树皆生意，壁上丹青有岁华。","禁直夜凉初赐被，讲筵秋近又宣麻。","神光郁郁冲牛斗，河汉层阴莫漫遮。"]},{"t":"史院秋祀三朝神御殿用郑编脩韵","f":"七言律诗","c":["银烛金莲禁署深，香飘秘殿碧沉沉。","鼎湖弓剑千年在，黼座衣冠五夜临。","帘外雨云飞野鸟，殿中燎火起巢禽。","悲丝急管俱增感，谁识朱颜白发心。"]},{"t":"彦脩秘监作亭阶前栽竹一个名一竿亭咸为赋诗","f":"七言律诗","c":["公子孤标绝世奇，亭前栽竹静相宜。","苍龙垂影云千尺，翠袖临风玉一枝。","特操不随春色改，高情只许岁寒知。","江头留得扁舟在，何日从君独钓时。"]},{"t":"送达天山融州大守","f":"七言律诗","c":["五马翩翩渡五溪，玉融更在桂林西。","连山晴黛分岩洞，列戍昏烟叠鼓鼙。","陇上梅花无雁过，庭前榕叶有莺啼。","使君自是金闺彦，暂为分忧及远黎。"]},{"t":"宜春盘龙寺","f":"七言律诗","c":["岩峰三十六盘通，塔殿高低翠谷中。","传法有宗僧业白，安身无语佛灯红。","松杉种得云千本，泉瀑飞来雪半空。","最喜老龙泓下卧，肯将霖雨致年丰。"]},{"t":"蓬轩","f":"七言律诗","c":["幽居轩槛越江边，鸿雁凫鹥在目前。","春涨还如天上坐，雪时浑是剡中船。","一枝梅月寒堪画，几树松涛夜不眠。","总把平生湖海兴，斫鱼酾酒赋诗篇。"]},{"t":"史馆上直次王应奉韵","f":"七言律诗","c":["玉堂高迥不宜冬，古木回廊浩荡风。","华盖紫微天咫尺，泰阶黄道日当中。","捷书迅急时闻奏，退食从容每自公。","衰晚腐儒何补报，祗须制作示无穷。"]},{"t":"送逯善上海道万户","f":"七言律诗","c":["帅符新拜紫髯翁，国饟深贤转漕功。","海水八荒浮地轴，云帆万斛动天风。","东吴民力今时困，中土军储昔自充。","报政归朝参大议，经邦事业属豪雄。"]},{"t":"筠庭","f":"七言律诗","c":["老屋城南倚翠屏，萧萧脩竹满前庭。","笋因夜雨侵苔长，枝共春云覆槛青。","深处石閒留客坐，隔林莺啭抚杯听。","故人诗句应题遍，藜杖何时一叩扃。"]},{"t":"次韵寄福建魏廉使","f":"七言律诗","c":["御沟冰泮水初流，绣斧朱幡上綵舟。","北极关河真壮观，南州风物总离忧。","花明苑树莺声晓，枫落吴江雁影秋。","眷注定知宣室召，归来应得从春游。"]},{"t":"浮云道院","f":"七言律诗","c":["道院孤高古翠微，满间山气静霏霏。","晓随白鹤迎风出，春共苍龙作雨归。","浮世纷华空在目，閒情舒卷自忘机。","无端却上蓬莱住，五色成章向日飞。"]},{"t":"鸡山隐居","f":"七言律诗","c":["自是山深好隐居，白云千亩在庭除。","凫飞每候仙人舄，酒熟时停长者车。","春尽草根俱是药，秋来柿叶总堪书。","旧家猿鹤多生怨，久欲从君卜里闾。"]},{"t":"代祀过信州苍岩贰守贻诗次韵以谢","f":"七言律诗","c":["群飞凡羽见孤凰，胸臆皆成五色章。","奕世公侯存故国，先朝相业踵遗芳。","银筝自度新调曲，金鸭时焚旧赐香。","惭愧相逢即相别，江东云树寸心长。"]},{"t":"上都秋日登眺","f":"七言律诗","c":["客里年光似水流，满城砧杵动羁忧。","沙头白露牛羊夕，塞上黄云鸿雁秋。","千里关河通王气，两都宫阙壮神州。","多情不用悲摇落，更为斜阳独倚楼。"]},{"t":"环翠楼","f":"七言律诗","c":["碧梧翠竹倚孱颜，故筑层楼与客攀。","剑气每留星汉上，山光只在雨帘间。","娟娟晓日开眉黛，蔼蔼春云拥髻鬟。","便欲买舟江海去，杖藜应许叩岩关。"]},{"t":"鳌峰石","f":"七言律诗","c":["鳌峰石在玉堂前，近与蓬莱御阁连。","积润出云秋漠漠，孤根承露夜娟娟。","土花剥尽生光怪，海峤移来阅岁年。","艮岳遗墟归草莽，金题犹识旧时镌。"]},{"t":"上官氏南楼","f":"七言律诗","c":["层轩百尺倚高秋，萧爽浑如庾亮楼。","云影每依帘侧畔，溪声只在树东头。","仙人岩石通霄汉，太乙藜灯直斗牛。","总道登临多雅兴，何时借鹤试相求。"]},{"t":"东安陈氏慕亲堂","f":"七言律诗","c":["城外云连郭隗台，草堂寂寞傍坟开。","碑铭有字人常读，宰树成行手自栽。","雊雉春迎寒食出，哺乌晴逐夕阳来。","百年霜露无穷思，击筑酬歌总是哀。"]},{"t":"坦明堂","f":"七言律诗","c":["东南佳丽独钱塘，君向青郊结草堂。","几曲云山分野色，满池秋水纳天光。","松阴落处琴书润，柳絮飞来枕簟凉。","衮衮京华尘土梦，好因鲈鲙踏吴航。"]},{"t":"戴宣使以差出建康因得过家","f":"七言律诗","c":["杨柳新条拂酒杯，都门望望百花开。","元臣建国罗群彦，使者宣劳出上台。","云路渐看华盖逼，乡关初见锦衣回。","此行不为鲈鱼鲙，莫待秋风击棹来。"]},{"t":"李氏义聚堂","f":"七言律诗","c":["锦里堂成聚弟兄，门门雍睦见仪型。","桑麻绕屋春千亩，风雨连床夜六经。","折去荆花依旧紫，种来慈竹镇长青。","贻谋更有无穷感，时向尊前赋鹡鸰。"]},{"t":"萧閒外舍次许可用承旨韵","f":"七言律诗","c":["东郊结屋川光近，内相题诗墨色新。","庭草常留青鹿卧，渚云惟许白鸥邻。","傍帘种竹秋声近，带石移花夕露匀。","野马尘埃浑不到，萧然门巷自家春。"]},{"t":"顺存堂","f":"七言律诗","c":["龙泉江上卜幽居，题扁当楣学士书。","堂下白花吹采凤，窗间锦瑟咏关雎。","猗兰有态春云近，棣萼多情昼日舒。","朋酒升堂家庆在，相看不乐更何如。"]},{"t":"至日和仲宝大学士韵","f":"七言律诗","c":["御扆当阳扇影回，乐声齐起殿前雷。","行天黄道常依日，报国丹心未许灰。","金锡衮衣归黼黻，琼楼玉宇尚崔嵬。","谢安再为苍生起，调化真宜法斗魁。"]},{"t":"墨梅","f":"七言律诗","c":["粲粲冰肌雪未暾，萧萧疏影写黄昏。","情深西子湖边树，梦入罗浮月下村。","万斛春光归笔力，一枝云气沁香魂。","清江寂寞杨丞远，无限风流此日存。"]},{"t":"黄隐士相过次韵","f":"七言律诗","c":["吾家华盖郁嵯峨，数亩蓬茅长薜萝。","愧我菲才宜隐退，知君有道幸相过。","风清杖屦迎岚出，春尽犁锄带雨歌。","架上有书尊有酒，相逢不乐又如何。"]},{"t":"和虞先生寿京师贾姑诗韵","f":"七言律诗","c":["慈颜九帙鬓如鸦，世族前朝宰相家。","天近县官时赐帛，春深孙子日扶车。","麻姑酒是长生药，阿母桃应几度花。","学士诗成无限思，五千里外望京华。"]},{"t":"送陈道士奉香归四明","f":"七言律诗","c":["暖烟芳草路迢迢，又送天香下九霄。","洞口桃花春欲笑，山头桂树晚难招。","麻姑酒榼藏丹室，徐福楼船驾海潮。","何日乘桴远相问，讵应无地老渔樵。"]},{"t":"听雨堂","f":"七言律诗","c":["兄弟多情有别离，昔年惆怅大苏诗。","青山听雨相思处，白日看云独坐时。","慈竹绕檐春瑟瑟，梧桐当户夜迟迟。","投簪未觉归来晚，尽散囊金对酒卮。"]},{"t":"强仲贤赴广东师帅幕","f":"七言律诗","c":["元戎分阃握兵符，筹昼须君答庙谟。","千里车来天北极，五羊城在海东隅。","香云荔子丹砂颗，清露芙蓉锦绣图。","早立勋名重邦国，莫令妖气傍江湖。"]},{"t":"九日燕南禁酒简赵子威佥宪","f":"七言律诗","c":["又与黄花负夙期，天南霜露满人衣。","酒尊有禁逢佳节，纱帽无情对落晖。","俯听秋声从树起，仰看云影送鸿飞。","登临不用增惆怅，咫尺承恩上紫微。"]},{"t":"燕南龙兴寺阁晚眺","f":"七言律诗","c":["倚天楼阁贮金仙，层栋犹题赵宋年。","混一南方今宇宙，英雄百战旧山川。","鱼龙水落秋江外，刍牧人归夕照边。","总为悲歌生慷慨，凭阑极目思凄然。"]},{"t":"关西道士求赋雪巢","f":"七言律诗","c":["一间素壁倚秋风，却拟巢林雪半空。","鍊得身形清似鹤，望来剑气白于虹。","洞箫窅窕留云住，牖户绸缪许月通。","更识船如天上坐，孤飞只合剡溪中。"]},{"t":"上巳日次韵","f":"七言律诗","c":["忆昨追随苑外车，风光九市见纷奢。","并儿玉带双龙佩，燕女金袍五凤花。","天乐声高仙仗肃，宸旌影动禁林赊。","当时讲席尊诸老，人到于今喜诵夸。"]},{"t":"欧阳建寅赴松江巡检","f":"七言律诗","c":["京华久客宦情微，身到江南即是归。","虎士刺船迎逻鼓，鲛人停杼望云扉。","蒹葭夜月风连海，粳稌春云水绕围。","自笑白头犹恋阙，何时五马借光辉。"]},{"t":"次赵伯友韵 其一","f":"七言律诗","c":["白发衰翁怜病久，青春游子叹归迟。","感君曾奏匡衡疏，怀国长吟杜甫诗。","苍海鱼龙仍衮衮，孤城花柳自熙熙。","千年遗恨同谁语，百世高情与尔期。"]},{"t":"次赵伯友韵 其二","f":"七言律诗","c":["百年道脉细于丝，长夜漫漫待旦迟。","先进常从周礼乐，专门仍授汉书诗。","微躬独步思绳武，大介重光仰缉熙。","已忍凄凉成病久，寸诚惟与古人期。"]},{"t":"游西湖承天寺赠月潭上人","f":"七言律诗","c":["中天台阁禁城西，春日游人出御堤。","满地落花驯鹿卧，千条弱柳乱莺啼。","窗涵水影金镛净，幡倚晴云绛节齐。","最喜上人能爱客，乘船仍约酒频携。"]},{"t":"宋枢密权公葬婺源之麓八世孙居都昌者作楼以望其丘陇于千里之外名曰寓思虞学士尝为赋诗今楼已废矣九世孙缉来求余诗赋此","f":"七言律诗","c":["异乡丘陇近蓬莱，层构当年望眼开。","千里江山遗刻在，百年霜露远孙来。","已无化鹤归华表，空有饥乌下碧苔。","寂寞孝思何所寓，断云衰草两堪哀。"]},{"t":"九日紫极宫次戴懋和韵 其一","f":"七言律诗","c":["老去杯悭易劝酬，年年挥泪望神州。","凤凰城阙金汤在，龙虎亭台翠辇游。","牛斗寒光通紫极，蓬莱弱水隔玄洲。","乌纱不受西风急，高阁凭江倚素秋。"]},{"t":"九日紫极宫次戴懋和韵 其二","f":"七言律诗","c":["忆昨追游禁苑寒，陇头红叶醉中看。","青蒲曾伏麒麟殿，白发能胜獬豸冠。","天上玉堂惟有梦，田间瓦缶竟无欢。","殊方久病悲摇落，笑啜茱萸强自宽。"]},{"t":"次韵寄康宗武","f":"七言律诗","c":["一自承恩乞鉴湖，几回清梦谒神都。","蒲萄天马穷边徼，粳稻云帆转越吴。","旸谷吠晨惊蜀犬，神祠鸣夜诧城狐。","隆中高卧空筹策，万里云霄羽翮孤。"]},{"t":"燕处会灵宫次姜步德韵","f":"七言律诗","c":["江上烟岚接地阴，仙家庭宇自云林。","玉堂金马成尘梦，草服黄冠称野心。","沧海鱼龙秋水落，瑶台风露夜寒深。","肯从世外寻丹诀，何事人间叹陆沉。"]},{"t":"浔阳舟中三首 其三","f":"七言律诗","c":["伏枕移床向小舟，江头渔父问何由？","风波接棹鱼龙冷，烟草迷津雁鹜秋。","往事几年怀内顾，狂澜百折任东流。","草玄不守扬雄宅，垂白空添宋玉愁。"]},{"t":"九江冬至日","f":"七言律诗","c":["愁坐孤城对日长，葭灰动处识微阳。","八方云物瞻新候，几树梅花忆故乡。","黄道春回天北陆，紫烟时想殿中央。","频年凤历催颁朔，曾插金貂侍玉皇。"]},{"t":"次韵示从学","f":"七言律诗","c":["东度关山马迹长，南浮江海雁随阳。","丹书玉篆发天语，金节绣衣辞帝乡。","放臣泣血竟何益，羁客哀吟殊未央。","故园云谷杂豺虎，寒木何枝依凤凰。"]},{"t":"高昌喜山近仁在江州为太常院使礼部尚书新其堂构各有名扁为赋三题馀未暇也 其一","f":"七言律诗","c":["江上小堂仍种竹，浑如一棹住江间。","芙蓉秋水三千顷，翠黛春云十二鬟。","凤管制来新谱在，渔竿留得钓丝閒。","牧羊庭远寒无树，裘马轻肥客未还。"]},{"t":"高昌喜山近仁在江州为太常院使礼部尚书新其堂构各有名扁为赋三题馀未暇也 其二","f":"七言律诗","c":["冥鶤化翮向南飞，栖息安危各有时。","秋入梧桐晴影薄，寒通牖户晓光迟。","青山是处瞻龙气，紫阁何年睹凤仪。","自叹蓬莱常五色，上林曾宿最高枝。"]},{"t":"高昌喜山近仁在江州为太常院使礼部尚书新其堂构各有名扁为赋三题馀未暇也 其三","f":"七言律诗","c":["飞花如席拂庐低，不辨行踪径已迷。","竟夕有书分户映，几年无榻见岩栖。","秦关拥道难容马，汉节禁寒尚牧羝。","曾忆钓蓑归旧隐，洞天高与白云齐。"]},{"t":"浔阳舟中三首 其一","f":"七言律诗","c":["百年头上著乌纱，一日江边踏钓槎。","病似相如空有赋，贫于杜甫更无家。","渔歌楚楚蒹葭月，樵笛村村踯躅花。","事业已随兵燹尽，青门惟守邵平瓜。"]},{"t":"九江杂咏书怀 其二","f":"七言律诗","c":["天地无情泪眼枯，故园松菊久荒芜。","秋风茅屋从谁葺，春日村醪只自沽。","万里关河迷宇宙，孤舟烟雨满江湖。","渥洼老骨空相顾，云汉高飞不易呼。"]},{"t":"冬至后九日","f":"七言律诗","c":["绣窗添线琯浮灰，玉烛迎阳晷影回。","雁度关河随朔气，龙依江海蛰神雷。","渐开柳眼窥春色，未放梅腮送酒杯。","药裹书签随处有，乡心岁事漫相催。"]},{"t":"次韵寄友 其一","f":"七言律诗","c":["旸谷东飞陆海灰，灵杓北顾帝车回。","波涛寒涌江间月，草木春移地底雷。","九奏钧天犹梦乐，十洲弱水不胜杯。","山楼笳鼓时时急，晏岁冰霜日日催。"]},{"t":"次韵寄友 其二","f":"七言律诗","c":["几年野烧着寒灰，此日楼船向海回。","万叠云烟秋似黛，一江风浪夜如雷。","歌残玉树浮空棹，梦入金茎渴露杯。","想待上林花未发，春光应得鼓声催。"]},{"t":"立春日","f":"七言律诗","c":["年年此日客殊方，谁拟今年住九江。","花鸟春愁诗漫兴，乾坤元气酒难降。","乡心华盖云千里，病目匡庐雪一窗。","到处青山薇可食，老来何必泪双双。"]},{"t":"除夕有感 其一","f":"七言律诗","c":["渔竿长在楚天涯，龙节虚随汉使槎。","世路风尘迷杞棘，故园烟雨忆桑麻。","两行泪对椒盘酒，一树春生蜡炬花。","人事乡书俱寂寞，不堪江上鼓频挝。"]},{"t":"除夕有感 其二","f":"七言律诗","c":["华盖芙蓉翠倚天，高堂綵服忆长年。","家人共守迎春酒，童稚争分压岁钱。","香雾煖浮金鸭动，蜡虹晴隔绛纱然。","鹤书一去无消息，白发沧江对雪眠。"]},{"t":"辛丑元日夜坐试笔","f":"七言律诗","c":["扶桑晓色压春云，江上香炉留夕曛。","坐来白日有佳兴，雪后青山无垢氛。","蛰龙三冬成久卧，鸣鸟百年今不闻。","遗经独在共谁语，太乙吹藜来夜分。"]},{"t":"赠聂克敬兼简宗武","f":"七言律诗","c":["岁晏匡庐积雪深，高松老鹤苦能禁。","海尘杳杳生春态，江水沄沄流夕阴。","无事庾楼留客赋，向来梁甫为谁吟。","渔樵旧侣如相问，鸥鹭寒盟尚可寻。"]},{"t":"夜月","f":"七言律诗","c":["处处关山泪眼明，悲笳又送断肠声。","芙蓉水冷秋无际，乌鹊枝寒夜屡惊。","黄道帝车还北极，紫垣天驷接南瀛。","多情不用悲摇落，万里江波月夕清。"]},{"t":"七夕大风","f":"七言律诗","c":["江头风急客衣凉，瓜果谁家月满堂。","五色在天曾补衮，七襄报日不成章。","机丝停杼空成绪，星汉乘槎竟杳茫。","自叹红颜今白发，人间养拙更何乡。"]},{"t":"次韵荅权纬","f":"七言律诗","c":["江湖波浪接鹍溟，牛斗光寒动客星。","兰芷风暄谁结佩，芙蓉水冷自扬舲。","周官礼乐先王度，汉代文章后世型。","衰病独怜头尽白，故人相见眼终青。"]},{"t":"赋樊氏茅屋","f":"七言律诗","c":["闻君茅屋住樊川，水影山光接几筵。","花径约来寻酒伴，柴门系着钓鱼船。","晴檐兴在从谁赋，秋树高风只自编。","亦有数椽华盖下，杖藜何日白云边。"]},{"t":"赠刘懋观写真","f":"七言律诗","c":["萧萧霜鬓隔风尘，却有刘郎为写真。","金马玉堂成昔梦，苍松白鹤伴閒身。","伤心南土衣冠少，极目中天日月新。","更许苏卿老归国，便应黄阁画麒麟。"]},{"t":"送人之西涧山长","f":"七言律诗","c":["巍巍宫庙涧之西，松桧萧森夹殿齐。","白屋衣冠存伏腊，青云步武见阶梯。","江湖夜月寒惊棹，桃李春阴雨满蹊。","昭代急贤无枉路，未应重席叹羁栖。"]},{"t":"老士安治书为使江东时尝构参云亭在京师属赋之","f":"七言律诗","c":["参云亭在宛溪头，持斧仙翁昔所游。","日月星辰天北极，山川草木地南洲。","门前车骑秋来好，竹上题诗醉后留。","回首江村烟树阔，至今犹忆旧风流。"]},{"t":"玉堂公宴次周学士韵","f":"七言律诗","c":["扈跸新随帝辇回，宾筵秩秩玉堂开。","禁庐下直辞天仗，内使传宣送御醅。","舞女分行花影动，歌工閒奏鼓声催。","衰年感遇惭无补，赖有诸公济世才。"]},{"t":"冯氏藏书堂","f":"七言律诗","c":["乔木依堂数亩阴，买书不惜散黄金。","简编总许儒生读，碑帖还从墨客临。","芸阁牙签晴睒睒，练囊萤火夜沉沉。","只今许下多贤士，始信君侯惠泽深。"]},{"t":"邓汝贞买妾得子南归云林","f":"七言律诗","c":["云林三十六峰齐，独振京尘向旧栖。","天上桃花新结子，水边杨柳已生稊。","浊醪对客秋三径，啼鸟催人雨一犁。","亦欲投簪江上去，为君移棹过金溪。"]},{"t":"赠日本诗僧","f":"七言律诗","c":["偶来金阙信相从，笑指扶桑浴日红。","处处写诗扬海屿，时时飞锡振天风。","归云每共经函在，行橐常因酒盏空。","吾道获麟惟掩涕，乘桴相问有谁同。"]},{"t":"次韵荅康宗武胡伯文","f":"七言律诗","c":["百年勋业鬓星星，又听流莺绿满庭。","茶与仙人分石鼎，酒从豪客索银瓶。","一犁春雨苏公圃，半曲湖光孺子亭。","更肯烟霞空寂寞，未应尘土叹飘零。"]},{"t":"留岩峰寺 其一","f":"七言律诗","c":["扁舟飘泊苦西东，此日栖迟野寺中。","岚气常疑庐岳雨，秋声还似大江风。","辋川花木图犹在，杜曲茅茨赋未工。","人事萧条乡土近，几时回首白云通。"]},{"t":"留岩峰寺 其二","f":"七言律诗","c":["岩谷风多秋叶飘，一径荒草凉萧萧。","已无幽芳媚野色，惟有老树存高标。","青山冉冉列鬟黛，白日往往逢渔樵。","仰天长叹竟何补，荷蓧长歌谁可招。"]},{"t":"次韵寄乡友 其一","f":"七言律诗","c":["伤心一视天无外，病目长怀日再中。","猎骑合袪云梦泽，楼船直驾海潮风。","二仪高下悲人力，万类枯荣识化工。","衰晚祗惭何报补，艰危终不拟穷通。"]},{"t":"次韵寄乡友 其二","f":"七言律诗","c":["风尘冉冉似蓬飘，犹有衡门拥艾萧。","锦里几家红叶树，华峰千仞碧云标。","晓因童子坡头牧，夕约邻翁谷底樵。","秋月春花随地有，归来莫待楚辞招。"]},{"t":"南溪精舍","f":"七言律诗","c":["前代遗墟浏水上，南溪栋宇见新题。","开山种药云千本，傍舍移秧雨一犁。","白鹤时从檐下宿，黄莺只在竹间啼。","尚方近觉声华起，却向金门听晓鸡。"]},{"t":"挽余忠宣公","f":"七言律诗","c":["沔阳舟楫势如飞，安庆孤城屹不支。","诸葛智谋天地閟，杲卿忠义鬼神知。","纵然身活到今日，未必人生无死期。","一片精忠元不改，男儿到此是男儿。"]},{"t":"题古木","f":"五言绝句","c":["铁石皆生色，冰霜有岁华。","春雷龙启蛰，星汉客乘槎。"]},{"t":"天台玉汉桥道院八咏 其一 玉溪桥","f":"五言绝句","c":["玉溪浮采鹢，金锁贯晴虹。","自是知津者，能成利涉功。"]},{"t":"天台玉汉桥道院八咏 其二 积果堂","f":"五言绝句","c":["几树枣如瓜，千年桃始华。","渠通沧海水，门倚赤城霞。"]},{"t":"天台玉汉桥道院八咏 其三 十二区","f":"五言绝句","c":["拣地循环种，名花取次开。","藏春何待坞，按律且衔杯。"]},{"t":"天台玉汉桥道院八咏 其四 梅竹庄","f":"五言绝句","c":["天香生玉树，云影动琅玕。","对酒惊春事，开门识岁寒。"]},{"t":"天台玉汉桥道院八咏 其五 缉云亭","f":"五言绝句","c":["琴罢月生渚，鹤归松满坡。","葺亭无尸牖，应是白云多。"]},{"t":"天台玉汉桥道院八咏 其六 招隐亭","f":"五言绝句","c":["书从北阙上，文自北山移。","樵牧俱生怨，耕锄已过时。"]},{"t":"天台玉汉桥道院八咏 其七 渊泉亭","f":"五言绝句","c":["秀出千黛螺，飞来半空雪。","天光净渟渟，秋声来淅淅。"]},{"t":"天台玉汉桥道院八咏 其八 外墅","f":"五言绝句","c":["山光分远近，云气异朝晡。","过客俱能赋，开轩即是图。"]},{"t":"秋山山景图","f":"五言绝句","c":["茅屋倚秋树，山楼延夕曛。","流来桥下水，半是洞中云。"]},{"t":"漉酒图","f":"五言绝句","c":["头上巾堪脱，尊中酒不空。","衡门松菊在，归卧北窗风。"]},{"t":"画龙","f":"五言绝句","c":["天用莫如龙，渊潜閟神功。","一朝起平陆，八表皆雷风。"]},{"t":"梅月窗","f":"五言绝句","c":["曾到西湖上，闻香不见梅。","推窗窥月色，竹外一枝开。"]},{"t":"青山绝处楼扁","f":"七言绝句","c":["中天隐隐碧芙蓉，楼阁深藏苐几重。","松叶满山行迹少，樵夫听得讲时钟。"]},{"t":"赤壁赋画图","f":"七言绝句","c":["水落江潭月满汀，秋光一色漾空青。","长歌窈窕吹箫者，祗许飞来白鹤听。"]},{"t":"水芙蓉","f":"七言绝句","c":["绛绡新制舞衣裳，翠盖亭亭度晚香。","祇恐君王恩易改，夜深风露不胜凉。"]},{"t":"画红梅","f":"七言绝句","c":["西湖月淡彩云飞，睡脸生霞酒力微。","谁道玉楼寒起粟，胭脂却染素娥衣。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其一","f":"七言绝句","c":["滦阳杨柳长新枝，无奈春寒力不支。","燕子归来风渐软，却似宫腰学舞时。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其二","f":"七言绝句","c":["晓来岚气不成霜，云染烟笼万缕长。","醉归谁敢争驰道，尽与君王控马缰。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其三","f":"七言绝句","c":["树绕离宫草共青，树底旌旗朝露零。","宫娥起伺羊车过，林梢斜月照华星。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其四","f":"七言绝句","c":["宫柳添来几百株，谁复天边种白榆。","马上贵人通国字，时折新条作笔书。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其五","f":"七言绝句","c":["神京高寒春力微，晴絮飞时花尚稀。","忽忆钱塘斜日岸，箫鼓画船扶醉归。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其六","f":"七言绝句","c":["陇头春深未识花，酒帘动处是谁家。","郎来莫折门前柳，昨夜东风初长芽。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其七","f":"七言绝句","c":["新赐金鞍选日骑，玉钗斜插两鬟垂。","长条拂着珍珠帽，只许东风细细吹。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其八","f":"七言绝句","c":["江头樵牧昔年逢，结茅临竹更依松。","柳条系得渔船住，长日醉眠谁问侬。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其九","f":"七言绝句","c":["绿阴芳草思凄凄，六宫传蜡煖烟迷。","沙堤不种隋家树，谁忆曲中乌夜啼。"]},{"t":"王继学赋柳枝词十首书于省壁至正十有三年扈跸滦阳左司诸公同追次其韵 其十","f":"七言绝句","c":["貂帽驼裘休叹侬，从官车骑莫从容。","柳花飞尽雪花起，才见西风又似冬。"]},{"t":"潘子华画上都花鸟","f":"七言绝句","c":["冰泮东风鸟力微，暖云将雨湿芳菲。","不知天上寒多少，谁剪春罗作舞衣。"]},{"t":"观弈图","f":"七言绝句","c":["仙人棋局静忘机，松下灵芝似玉肥。","樵客归时柯已烂，云间谁制芰荷衣。"]},{"t":"闻桂道人","f":"七言绝句","c":["八月天香满界飘，广寒宫外影萧萧。","不从玉兔求残药，却与云山伴寂寥。"]},{"t":"掀篷图","f":"七言绝句","c":["清江杨丞天下奇，每能拈笔写横枝。","暗香疏影黄昏后，曾忆掀篷对月时。"]},{"t":"送人归清江省亲","f":"七言绝句","c":["远树惊寒线在衣，西风吹雪作花飞。","清江碧嶂秋光里，不为鲈鱼也合归。"]},{"t":"大驾南归至龙虎台迎候者皆于昌平胄监岁馆旧县何氏至正九年八月监丞吴当独来馆人持祭酒司业旧题索赋 其一","f":"七言绝句","c":["当关龙虎拥层台，此地年年翠辇回。","八月千官瞻候日，旧陪词馆小臣来。"]},{"t":"大驾南归至龙虎台迎候者皆于昌平胄监岁馆旧县何氏至正九年八月监丞吴当独来馆人持祭酒司业旧题索赋 其二","f":"七言绝句","c":["尔家门巷自清幽，新辟轩窗许客留。","北望居庸天咫尺，白云红树倚高秋。"]},{"t":"赠淮安屯府从事","f":"七言绝句","c":["长淮木落正纷纷，从事衔书逐雁群。","八月江寒鱼似玉，列屯秋净稻如云。"]},{"t":"挟弹图","f":"七言绝句","c":["平沙浅草雨初乾，时见飞花到马鞍。","花树止留巢凤鸟，王孙何处试金丸。"]},{"t":"云林亭","f":"七言绝句","c":["幽亭古木净萧萧，江月云山远莫招。","昨夜西风吹梦去，共谁相对说渔樵。"]},{"t":"宣和䳺鹑","f":"七言绝句","c":["九重拈笔写清秋，草底微禽亦见收。","回首故宫花石外，离离禾黍不胜忧。"]},{"t":"孙氏孝义","f":"七言绝句","c":["倚庐常近墓人家，种树留巢返哺鸦。","门外桑麻春几顷，东风开遍紫荆花。"]},{"t":"携琴图","f":"七言绝句","c":["偶因秋兴携琴去，古木苍藤何处村。","行过溪桥山路合，白云千亩不知门。"]},{"t":"蔡氏藏先世诰敕","f":"七言绝句","c":["无复前朝旧典型，百年文物尽凋零。","蔡家孙子风流在，爱惜黄麻似六经。"]},{"t":"息斋竹月","f":"七言绝句","c":["苍龙翻石湿云交，鸣玉参差出凤巢。","翠黛晓凉香袖薄，一钩纤月在林梢。"]},{"t":"赠墨工侯务本次虞学士韵 其一","f":"七言绝句","c":["御床玄璧进龙香，奎阁当年诧豫章。","此日侯家新制作，采烟凝液总仙方。"]},{"t":"赠墨工侯务本次虞学士韵 其二","f":"七言绝句","c":["窗下云英透纸香，白头惭愧恋文章。","玉堂天上成春梦，珍赐何时出尚方。"]},{"t":"画鹤","f":"七言绝句","c":["云汉寥寥雪羽毛，海风吹月倚秋高。","石田瑶草俱情思，时见临池一吮毫。"]},{"t":"觅盆梅","f":"七言绝句","c":["病中犹未见梅花，何日尧夫驾小车。","为觅小盆分少树，东风如到野人家。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其一","f":"七言绝句","c":["沙岭风清宿雨多，白云如雪夜陂陀。","涧泉十里九曲折，北向天边作御河。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其二","f":"七言绝句","c":["雨过平沙不染泥，綵索凌风御帐齐。","宫臣报道晓寒浅，有个黄鹂深树啼。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其三","f":"七言绝句","c":["宫车调得马蹄匀，细草轻风不动尘。","织成翠羽垂珠幕，缕就黄金结绣茵。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其四","f":"七言绝句","c":["露下穹庐暑气苏，卧看织女映黄姑。","山泉响似江南雨，林下不闻啼鹧鸪。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其五","f":"七言绝句","c":["马群弥野草连云，当年玉帐度秋春。","迎日捷书频送喜，内间赐与出金银。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其六","f":"七言绝句","c":["羽猎长年从翠华，麋鹿生茸草茁芽。","射得黄羊充内膳，更喜江南新贡茶。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其七","f":"七言绝句","c":["果熟冰盘进御黄，秘殿挥毫对日长。","元臣补衮应无阙，新赐宫衣自上方。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其八","f":"七言绝句","c":["殿头云气尽成龙，水晶帘影散高春。","阿母传杯池上宴，帝子吹箫月下逢。"]},{"t":"竹枝词和歌韵自扈跸上都自沙岭至滦京所作 其九","f":"七言绝句","c":["霓旌移仗蕊珠宫，云母屏门不隔风。","花外侍臣成久立，听得新歌乐意同。"]},{"t":"青宫受宝朝贺日次韵 其一","f":"七言绝句","c":["百年文物际重熙，丽日祥云昼刻迟。","上相传宣催草诏，看君落笔玉堂时。"]},{"t":"青宫受宝朝贺日次韵 其二","f":"七言绝句","c":["殿外霓旌漾晓晖，炉烟浮动衮龙衣。","璚楼贝阙天中起，五色云霞在翠微。"]},{"t":"青宫受宝朝贺日次韵 其三","f":"七言绝句","c":["天乐声中舞序陈，千官花外驻车轮。","春宫初试黄麾仗，宝盖珠幡队队新。"]},{"t":"青宫受宝朝贺日次韵 其四","f":"七言绝句","c":["绿树重重秘殿阴，画堂甲观九重深。","青宫昨夜初承诏，丹扆今朝又进箴。"]},{"t":"青宫受宝朝贺日次韵 其五","f":"七言绝句","c":["日出苍龙紫雾开，金门宣赦近臣来。","书条字字皆宽大，万姓欢声动地雷。"]},{"t":"青宫受宝朝贺日次韵 其六","f":"七言绝句","c":["大安高阁正当中，龙虎旌旗卫两宫。","近日春坊谁辅导，相君班序冠三公。"]},{"t":"青宫受宝朝贺日次韵 其七","f":"七言绝句","c":["禁直周庐接上台，银河秋傍紫垣来。","为郎莫笑冯唐老，立马金门待晓开。"]},{"t":"青宫受宝朝贺日次韵 其八","f":"七言绝句","c":["宫臣侍侧近炉熏，衣上龙乘五绣云。","鸣玉锵金俱鼎食，早思偃武与修文。"]},{"t":"青宫受宝朝贺日次韵 其九","f":"七言绝句","c":["殿阁薰风奏舜弦，大明宫树不凝烟。","圣人恭默惟思治，日历凭谁细细编。"]},{"t":"青宫受宝朝贺日次韵 其十","f":"七言绝句","c":["深宫无处不开花，玉烛调阳运帝车。","不是人间春易老，风光长只在天家。"]},{"t":"自然亭","f":"七言绝句","c":["盘结松萝覆顶青，云山四面作帏屏。","秋风棋局无人看，夜月琴声有鹤听。"]},{"t":"九月十日出城","f":"七言绝句","c":["病耄犹知发出狂，卧嗔恶少强移床。","丈夫死义无悲泪，市上傍观为两行。"]},{"t":"出湖","f":"七言绝句","c":["鸿雁声低日己晡，扁舟渺渺出平湖。","何时却为鲈鱼脍，写作寒江独钓图。"]},{"t":"十六日舁床入城","f":"七言绝句","c":["舟子舁床入市廛，病躯仰面看青天。","不知城郭还何似，听得行人叹昔年。"]},{"t":"谩成 其一","f":"七言绝句","c":["豫章城里听秋风，却向匡庐去住冬。","白发数行非俗骨，青山千仞有云松。"]},{"t":"谩成 其二","f":"七言绝句","c":["十洲麒凤落江湖，遗老相逢说旧都。","春日琼林看锡宴，天门金榜听传胪。"]},{"t":"谩成 其三","f":"七言绝句","c":["昔年策士奏题名，西内传宣御仗迎。","金织承筐怀旧赐，白头何以荅升平。"]},{"t":"谩成 其四","f":"七言绝句","c":["战骨生尘塞草长，将军己拜右贤王。","节旄落尽苏卿老，渤海沙飞尚牧羊。"]},{"t":"谩成 其五","f":"七言绝句","c":["霜月横空雁不眠，夜寒边燧尚传烟。","伤心江上垂纶客，不为鲈鱼系钓船。"]},{"t":"杂咏","f":"七言绝句","c":["江头雄锁控东西，长叹忠臣效节时。","满目山川天险在，不将版锸虑安危。"]},{"t":"忠臣","f":"七言绝句","c":["万里江淮接楚舒，连云楼橹见储胥。","睢阳不独张巡死，汗简应留太史书。"]},{"t":"宪使储布哈守楚元帅余阙守舒 其一","f":"七言绝句","c":["万方海宇一封疆，郡邑胥豪玩宪章。","寂寞荒城今第宅，家家故牍满新墙。"]},{"t":"宪使储布哈守楚元帅余阙守舒 其二","f":"七言绝句","c":["败苇萧萧故垒秋，江山如画一渔舟。","怪来不起临濠兴，病久愁深泪易流。"]},{"t":"宪使储布哈守楚元帅余阙守舒 其三","f":"七言绝句","c":["庐岳层层耸碧空，仙岩佛塔白云通。","几多楼阁青红地，尽在寒烟野蔓中。"]},{"t":"咏怀","f":"七言绝句","c":["昔贤讲道秩宾筵，五老香炉蔼紫烟。","前代衣冠今寂寂，故溪风月自年年。"]},{"t":"先子讲道濂溪书院今四十馀年 其一","f":"七言绝句","c":["关雎麟趾久无声，谁共周官识治平。","独抱遗经身己老，空山落月梦魂惊。"]},{"t":"先子讲道濂溪书院今四十馀年 其二","f":"七言绝句","c":["江头风月夜萧萧，旅馆寒灯共寂寥。","三月病来忘肉味，九天清夜听箫韶。"]},{"t":"先子讲道濂溪书院今四十馀年 其三","f":"曲","c":["春雨黄精似玉?，东风漠漠紫山薇。","饥来白石还堪煮，自叹时人服食稀。"]},{"t":"先子讲道濂溪书院今四十馀年 其四","f":"七言绝句","c":["柳外郊墟旧战场，寒芜秋燐暮云黄。","渐看三月莺花里，陌上新苗陇上桑。"]},{"t":"先忌日","f":"七言绝句","c":["云谷烟村事事非，凫飞不到雁来稀。","楸梧几个人千里，不独今朝泪满衣。"]},{"t":"观大明殿图","f":"七言绝句","c":["大明宫阙五云端，簪笔趋朝老从官。","白发十年江海外，人间写作画图看。"]},{"t":"读史 其一","f":"七言绝句","c":["周业凌迟伯失宗，纷纷功利起衡从。","时君不识真王佐，卿禄宁辞十万钟。"]},{"t":"读史 其二","f":"七言绝句","c":["牛酒争迎暴已除，沛中屠贩漫高车。","鸿沟更举真筹策，圮上功成一卷书。"]},{"t":"读史 其三","f":"七言绝句","c":["受命趋关定约时，鄛翁多算竟何为。","可怜空碎鸿门玉，天下雄雌亦易知。"]},{"t":"读史 其四","f":"七言绝句","c":["灭仇报主已成功，还定三秦众策同。","西楚能存韩社稷，赤松无迹到关中。"]},{"t":"读史 其五","f":"七言绝句","c":["四海为家辨本支，大封同姓奠邦基。","留侯漫使储君固，遗毒无端及爱儿。"]},{"t":"读史 其六","f":"七言绝句","c":["女祸几令社稷危，安刘一语已先知。","良平无术强根本，功在诸君左袒时。"]},{"t":"读史 其七","f":"七言绝句","c":["盖世功名意气雄，楚齐国大势难容。","从容进退知天道，一邑封留事赤松。"]},{"t":"读史 其八","f":"七言绝句","c":["先汉雄词后世无，子云学业冠西都。","大醇难掩终身玷，直笔凄凉莽大夫。"]},{"t":"读史 其九","f":"七言绝句","c":["草罢玄经雪满头，美新兴颂不深谋。","千年遗恨曾投阁，金谷何人肯坠楼。"]},{"t":"读史 其十","f":"七言绝句","c":["桐江波上有渔蓑，东汉流风节义多。","大器已移名独在，犹将公论作干戈。"]},{"t":"读史 其十一","f":"七言绝句","c":["九夷辟地识遗贤，白帽端居木榻穿。","卓行至今推有道，建安词藻漫流传。"]},{"t":"读史 其十二","f":"七言绝句","c":["天自西倾水自东，三分割据识英雄。","仲谋有子曹郎在，盖世功名仅汉中。"]},{"t":"读史 其十三","f":"七言绝句","c":["一方僻险控孙曹，兵术相疑治道高。","尚父鹰扬身未死，讵应典午得称豪。"]},{"t":"读史 其十四","f":"七言绝句","c":["六朝才气苦厌厌，归去辞高义独严。","忧世乐天真有道，千年处士晋陶潜。"]},{"t":"礼乐 其一","f":"七言绝句","c":["束帛难招鲁两生，奉常绵蕞乱纵横。","满朝将相轻年少，治道难因礼乐行。"]},{"t":"礼乐 其二","f":"七言绝句","c":["伦纪无章古道昏，哇声乱耳讵堪论。","千年不睹真儒效，空忆河间礼乐存。"]},{"t":"连旬大雪 其一","f":"七言绝句","c":["瘦骨棱层病未安，江天风雪夜漫漫。","布衾铁石浑无寐，难得梅花入梦看。"]},{"t":"连旬大雪 其二","f":"七言绝句","c":["平施翠壑与丹崖，风磴云门处处埋。","直待东风花尽发，却寻布袜踏青鞋。"]},{"t":"可叹 其一","f":"七言绝句","c":["忠义曾书宋两都，一时直笔共描摹。","万方顺逆苍天在，遗臭难称莽大夫。"]},{"t":"可叹 其二","f":"七言绝句","c":["汉水生波郡邑墟，空传楚魄葬江鱼。","前年节钺秋江上，满纸祈哀逐客书。"]},{"t":"可叹 其三","f":"七言绝句","c":["碧桃红杏艳阳天，礼聘相期举按贤。","肠断关河时听雁，琵琶却在卖茶船。"]},{"t":"谩题 其一","f":"七言绝句","c":["上林高处凤凰栖，羽翮垂云五色辉。","黄竹雪深梧影落，山鸡临水炤毛衣。"]},{"t":"谩题 其二","f":"七言绝句","c":["日出扶桑海不惊，曾将巨钓掣鲵鲸。","一蓑回首秋江上，卧听兰苕翡翠鸣。"]},{"t":"谩题 其三","f":"七言绝句","c":["香炉峰色白巉巉，黄独无苗雪满镵。","燕子经年江上别，东风回首听呢喃。"]},{"t":"五老峰","f":"七言绝句","c":["五老峰前雪未消，烟岚染处夕阳挠。","沽来尊酒寻梅树，钓得江鱼上柳条。"]},{"t":"立春日感旧 其一","f":"七言绝句","c":["南楼谯鼓北楼钟，楼外泥牛綵仗丛。","黄道泰阶春浩荡，苍龙观阙晓曈昽。"]},{"t":"立春日感旧 其二","f":"七言绝句","c":["麒麟烟树凤凰毛，列侍趋朝礼独劳。","中使传宣排内宴，御园春动乐声高。"]},{"t":"立春日感旧 其三","f":"七言绝句","c":["春盘生菜翠如丝，内赐金幡映白髭。","前度桃花何处去，故园花草不胜思。"]},{"t":"立春日感旧 其四","f":"七言绝句","c":["照眼榴花酒入唇，愁颜衰鬓又逢春。","御沟冰泮河鱼美，惆怅江波有钓纶。"]},{"t":"春思","f":"七言绝句","c":["虎迹烟村少室墟，羊肠尘路太行车。","上林应射春归羽，江海累臣有帛书。"]},{"t":"除夕","f":"七言绝句","c":["几年别却帝城傩，种树书传郭橐驼。","华盖芙蓉秋色里，钓竿犹伴旧时蓑。"]},{"t":"与同馆戏续前韵 其一","f":"七言绝句","c":["东驱海若百年傩，尚度龙沙几两驼。","春雨莘郊留负耒，秋风渭水起渔蓑。"]},{"t":"与同馆戏续前韵 其二","f":"七言绝句","c":["燕歌赵舞国人傩，塞下牛羊塞上驼。","烟草随营飞猎骑，毡城无地挂耕蓑。"]},{"t":"与同馆戏续前韵 其三","f":"七言绝句","c":["紫髯都护气降傩，姬妾毡车橐载驼。","马挏浓於燕市酒，貂裘多似野人蓑。"]},{"t":"与同馆戏续前韵 其四","f":"七言绝句","c":["金目横戈夜进傩，锦幪负毂晓鸣驼。","灯前尽理朝天佩，林下谁缝钓雪蓑。"]},{"t":"与同馆戏续前韵 其五","f":"七言绝句","c":["仪凤青娥杂戏傩，肉峰翠釜荐珍驼。","碧桃天上云千树，白发江头雪一蓑。"]},{"t":"与同馆戏续前韵 其六","f":"七言绝句","c":["未踏猖狂举世傩，长安紫陌望铜驼。","陶公门外犹存菊，严子滩前不解蓑。"]},{"t":"与同馆戏续前韵 其七","f":"七言绝句","c":["尘眼争看楚俗傩，书灯独对汉时驼。","歌声无复渔家傲，处处金章换绿蓑。"]},{"t":"与同馆戏续前韵 其八","f":"七言绝句","c":["赤子妖成绛帻傩，皇都尘接紫关驼。","故人风雪谁联骑，野老江湖独拥蓑。"]},{"t":"与同馆戏续前韵 其九","f":"七言绝句","c":["蛮隶横过绝类傩，海艘任载岂烦驼。","杜鹃花外春连屋，布谷声中雨一蓑。"]},{"t":"梦登书阁","f":"七言绝句","c":["匡卢晴雪自㠝岏，万里清江一棹寒。","自笑老来情思别，九天楼阁梦中看。"]},{"t":"咏归 其一","f":"七言绝句","c":["看云不用买山钱，带雨宜翻种秫田。","白发数茎非故态，青山何日是归年。"]},{"t":"咏归 其二","f":"七言绝句","c":["荷花香里白鸥飞，绿树浓阴拂石矶。","一枕清风长夏簟，云边何日钓船归。"]},{"t":"咏归 其三","f":"七言绝句","c":["稻畦黄处树多红，山色岚光紫翠通。","茅屋数间流水外，一丝何日对秋风。"]},{"t":"咏归 其四","f":"七言绝句","c":["苍松翠竹映溪沙，溪上寒梅树树花。","十月瓮头春酒熟，杖藜何日到山家。"]},{"t":"讲仪","f":"七言绝句","c":["山城马足动红尘，杂沓晨趋服色新。","绵蕞草仪谁所具，伤心半是大廷臣。"]},{"t":"长生院作寿 其一","f":"七言绝句","c":["蓬莱云气合从龙，肠断关山几万重。","水落城空山未晓，长生院里鼓逢逢。"]},{"t":"长生院作寿 其二","f":"七言绝句","c":["天秩民彝不可磨，伤心蚁穴与蜂窠。","无端紫绶红尘里，犹说先朝第几科。"]},{"t":"李节妇田氏 其一","f":"七言绝句","c":["仙李移根雨露边，青春江汉共风烟。","千年事往蟠桃熟，黄竹歌传阿母筵。"]},{"t":"李节妇田氏 其二","f":"七言绝句","c":["绿鬓飞蓬四岁儿，寒机对月夜眠迟。","碧梧翠竹春云合，斜日慈乌返哺时。"]},{"t":"李节妇田氏 其三","f":"七言绝句","c":["江上莺花满目春，冰霜皎皎百年身。","自从破镜留孤影，锦瑟无声落燕尘。"]},{"t":"李节妇田氏 其四","f":"七言绝句","c":["朋酒升堂着舞衣，忘忧草色动春晖。","贻谋曾授三迁教，断缕犹存旧织机。"]},{"t":"李节妇田氏 其五","f":"七言绝句","c":["廉耻风移士节隳，壸仪犹足正民彝。","世情无限伤心地，惆怅琵琶掩面时。"]},{"t":"中秋对月口号 其一","f":"七言绝句","c":["古木昏鸦接翅飞，扶桑顾兔倍光辉。","广寒梦到嫦娥殿，新剪红霓制舞衣。"]},{"t":"中秋对月口号 其二","f":"七言绝句","c":["静听新人笑语声，天寒翠袖若为情。","举头不辨山河影，坐看儿童斗眼明。"]},{"t":"中秋对月口号 其三","f":"七言绝句","c":["豫章城头百尺楼，三年明镜炤人愁。","五老峰前秋色里，寸心折尽大刀头。"]},{"t":"归舟湖中梦至上都","f":"七言绝句","c":["归舟日日向南风，积雨初收浪拍空。","梦入龙冈清暑地，夜凉万斛水晶宫。"]},{"t":"八月二十四日","f":"七言绝句","c":["丑夜城头烈炬红，数声笳起戍楼空。","江山如旧豪华去，无食无衣一病翁。"]},{"t":"宣圣庙","f":"七言绝句","c":["百年如见鲁灵光，一炬堪怜瓦砾场。","秋水满池门独在，古槐依旧带斜阳。"]},{"t":"丑月六日见迫趋升抗论力争复絷于小舟龙开河口累夕惊风怒涛中六日夜至十有二日大雪冱冻病卧赋此 其一","f":"七言绝句","c":["长夜漫漫雪一篷，有衾如铁卧如弓。","窖中犹拥胡姬暖，未信当年属国穷。"]},{"t":"丑月六日见迫趋升抗论力争复絷于小舟龙开河口累夕惊风怒涛中六日夜至十有二日大雪冱冻病卧赋此 其二","f":"七言绝句","c":["曾忆黄河守冻船，鱼肥肉美酒如泉。","半生辛苦成何事，衰病饥寒雪里眠。"]},{"t":"朱矶除夕","f":"七言绝句","c":["骇浪惊风动楚天，乡心羁思漫年年。","鲈鱼不受寒江钓，今夜朱矶雪满船。"]},{"t":"即事","f":"七言绝句","c":["繁华一夕怨西风，金雁钿蝉镜影空。","咫尺关山春梦里，桃花又向别人红。"]},{"t":"衡山春游图","f":"七言绝句","c":["雁书不到祝融峰，怅望苍梧驻六龙。","尚欲暮年专一壑，白云深处寄行踪。"]},{"t":"赠樊秀才","f":"七言律诗","c":["忆昨承恩乞鉴湖，几回清梦谒神都。","葡萄天马来边徼，粳稻云帆出越吴。","旸谷吠晨惊蜀犬，神祠乘夜托城狐。","龙钟卧病空筹策，万里云霄羽翮孤。"]}]};